/**
 * Unit tests for the KEYLESS HEURISTIC DIRECTOR (`heuristic.ts`).
 *
 * The contract the heuristic must always satisfy, for ANY reasonable brand kit:
 *   1. `VideoSpec.parse()` succeeds (schema-valid).
 *   2. `lintSpec().ok` is `true` (anti-slop-clean — §4 guardrails).
 *   3. `validateSceneRefs()` returns `[]` (narrative grammar holds).
 *   4. It is pure + deterministic (same input → byte-identical output).
 *
 * Run with vitest (`vitest run src/llm/heuristic.test.ts`). No network, no LLM,
 * no clock, no mocks — the director is a pure function.
 */
import { describe, it, expect } from "vitest";

import { VideoSpec, lintSpec } from "../spec";
import { validateSceneRefs } from "./director";
import { heuristicDirect, type DirectorBrandKit } from "./heuristic";

/* -------------------------------------------------------------------------- */
/*  Synthetic brand kits — three distinct shapes                               */
/* -------------------------------------------------------------------------- */

/** A house brand (dark) — should bind to `dark-cinematic` via the locked map. */
const YUPCHA: DirectorBrandKit = {
  id: "yupcha",
  url: "https://yupcha.com",
  name: "Yupcha",
  palette: {
    bg: "#07090d",
    surface: "#11151c",
    text: "#f2f5f8",
    textDim: "#8a94a3",
    accent: "#3fe0c5",
    accent2: "#ff8a5b",
    gradientText: ["#3fe0c5", "#7aa2ff"],
  },
  fonts: ["Space Grotesk"],
  screens: [
    { key: "yupcha/agent-home", role: "hero" },
    { key: "yupcha/dashboard", role: "screenshot" },
    { key: "yupcha/scoring", role: "screenshot" },
  ],
  copy: [
    { text: "The Agentic Hiring Platform", kind: "headline" },
    { text: "Run end-to-end hiring workflows with AI agents.", kind: "value-prop" },
    { text: "Adaptive interviews", kind: "subhead" },
    { text: "Complete Anti-Cheating", kind: "subhead" },
    { text: "Fair Candidate Scoring", kind: "subhead" },
    { text: "Autonomous Interviews for any field.", kind: "value-prop" },
    { text: "The Future of AI Hiring is Agentic.", kind: "value-prop" },
  ],
  voice: "technical-confident",
};

/** An arbitrary LIGHT brand — no house binding → palette heuristic → editorial. */
const WARM_ARBITRARY: DirectorBrandKit = {
  id: "acmehash",
  url: "acme.io",
  name: "Acme Notes",
  palette: {
    bg: "#fbfaf7",
    surface: "#f1efe9",
    text: "#1a1714",
    textDim: "#6b655c",
    accent: "#c8553d",
    // no accent2 — exercises the optional-accent2 fallback in callouts.
  },
  fonts: ["Newsreader"],
  screens: [{ key: "acme/editor", role: "hero" }],
  copy: [
    { text: "Notes that write themselves.", kind: "headline" },
    { text: "Capture ideas before they vanish.", kind: "value-prop" },
  ],
};

/**
 * A DEGRADED, minimal kit — empty copy, a video-like screen key, no accent2, an
 * unparseable bg. The heuristic must still produce a valid, lint-clean spec
 * (filtering the clip key, synthesizing copy, defaulting to a dark register).
 */
const DEGRADED: DirectorBrandKit = {
  id: "x1",
  name: "Glitch",
  palette: {
    bg: "not-a-color",
    surface: "#222222",
    text: "#eeeeee",
    textDim: "#999999",
    accent: "#7c5cff",
  },
  // The only "screen" is a video clip — must be filtered so screen-is-still holds.
  screens: [{ key: "glitch/demo.mp4", role: "hero" }],
  copy: [],
};

const KITS: ReadonlyArray<[string, DirectorBrandKit]> = [
  ["yupcha (dark house brand)", YUPCHA],
  ["warm arbitrary (light, no accent2)", WARM_ARBITRARY],
  ["degraded (empty copy, clip screen, bad bg)", DEGRADED],
];

/* -------------------------------------------------------------------------- */
/*  Contract: every kit yields a schema-valid, lint-clean, narrative-sane spec */
/* -------------------------------------------------------------------------- */

describe("heuristicDirect — contract per brand kit", () => {
  for (const [name, kit] of KITS) {
    describe(name, () => {
      const spec = heuristicDirect(kit);

      it("is schema-valid (VideoSpec.parse)", () => {
        expect(() => VideoSpec.parse(spec)).not.toThrow();
        expect(VideoSpec.safeParse(spec).success).toBe(true);
      });

      it("is anti-slop-clean (lintSpec.ok)", () => {
        const r = lintSpec(spec);
        expect(r.violations).toEqual([]);
        expect(r.ok).toBe(true);
      });

      it("obeys narrative grammar (validateSceneRefs)", () => {
        expect(validateSceneRefs(spec)).toEqual([]);
      });

      it("threads the kit's brandKitId + valid palette swatches unchanged", () => {
        expect(spec.brandKitId).toBe(kit.id);
        // Valid swatches pass through byte-for-byte (no styling). All three kits
        // carry a valid `accent`; only the degraded kit has an unparseable `bg`,
        // which is correctly substituted with the safe default.
        expect(spec.palette.accent).toBe(kit.palette.accent);
      });

      it("assembles the conversion template (Hook first, CTA last)", () => {
        expect(spec.scenes[0].component).toBe("Hook");
        expect(spec.scenes[spec.scenes.length - 1].component).toBe("CTA");
        const productCount = spec.scenes.filter(
          (s) => s.component === "ProductShot",
        ).length;
        expect(productCount).toBeGreaterThanOrEqual(1);
      });

      it("caps feature beats at ≤4 and proof at ≤1", () => {
        const features = spec.scenes.filter(
          (s) => s.component === "FeatureBeat",
        ).length;
        const proofs = spec.scenes.filter((s) => s.component === "Proof").length;
        expect(features).toBeLessThanOrEqual(4);
        expect(proofs).toBeLessThanOrEqual(1);
      });

      it("gives every VO-bearing scene caption-able text", () => {
        for (const s of spec.scenes) {
          if (s.vo) expect(s.vo.text.trim().length).toBeGreaterThan(0);
        }
      });
    });
  }
});

/* -------------------------------------------------------------------------- */
/*  Preset selection                                                           */
/* -------------------------------------------------------------------------- */

describe("heuristicDirect — preset selection", () => {
  it("binds the dark house brand to dark-cinematic", () => {
    expect(heuristicDirect(YUPCHA).preset).toBe("dark-cinematic");
  });

  it("falls to editorial for a light arbitrary brand", () => {
    expect(heuristicDirect(WARM_ARBITRARY).preset).toBe("editorial");
  });

  it("defaults a bad-bg kit to the dark register", () => {
    expect(heuristicDirect(DEGRADED).preset).toBe("dark-cinematic");
  });

  it("honours a valid goal.preset override", () => {
    expect(heuristicDirect(YUPCHA, { preset: "minimal-mono" }).preset).toBe(
      "minimal-mono",
    );
  });

  it("threads a valid bg swatch through unchanged", () => {
    expect(heuristicDirect(YUPCHA).palette.bg).toBe(YUPCHA.palette.bg);
    expect(heuristicDirect(WARM_ARBITRARY).palette.bg).toBe(
      WARM_ARBITRARY.palette.bg,
    );
  });
});

/* -------------------------------------------------------------------------- */
/*  Purity / determinism                                                       */
/* -------------------------------------------------------------------------- */

describe("heuristicDirect — pure + deterministic", () => {
  it("same input → byte-identical output", () => {
    const a = heuristicDirect(YUPCHA, { format: "9:16" });
    const b = heuristicDirect(YUPCHA, { format: "9:16" });
    expect(JSON.stringify(a)).toBe(JSON.stringify(b));
  });

  it("does not mutate its inputs", () => {
    const kitBefore = JSON.stringify(WARM_ARBITRARY);
    const goal = { angle: "lead with the capture pain" };
    const goalBefore = JSON.stringify(goal);
    heuristicDirect(WARM_ARBITRARY, goal);
    expect(JSON.stringify(WARM_ARBITRARY)).toBe(kitBefore);
    expect(JSON.stringify(goal)).toBe(goalBefore);
  });

  it("threads goal.format through", () => {
    expect(heuristicDirect(YUPCHA, { format: "1:1" }).format).toBe("1:1");
  });
});

// Unit tests for the pure `breathe` text normalizer. Run with:
//   node --import tsx --test src/vo/pacing.test.ts
// (no network / no ffmpeg — `padSilence` is exercised by the live pipeline proof).

import assert from "node:assert/strict";
import { test } from "node:test";
import { breathe } from "./pacing";

test("collapses whitespace and trims", () => {
  assert.equal(breathe("  hire   smarter  "), "hire smarter.");
});

test("adds a space after a missing inter-sentence boundary", () => {
  assert.equal(
    breathe("the top of the funnel.Let an agent run it."),
    "the top of the funnel. Let an agent run it.",
  );
});

test("appends terminal punctuation when the line ends on a word", () => {
  assert.equal(breathe("Yupcha runs it without you"), "Yupcha runs it without you.");
});

test("does not double-punctuate an already-terminated line", () => {
  assert.equal(breathe("Available today!"), "Available today!");
  assert.equal(breathe("Start free at yupcha dot com."), "Start free at yupcha dot com.");
});

test("preserves words and em-dashes; only touches whitespace/terminal punct", () => {
  const src = "The agent conducts the interview live — asking, listening, and adapting.";
  assert.equal(breathe(src), src);
});

test("is pure: same input -> identical output", () => {
  const s = "Hiring eats your week.Yupcha runs it without you";
  assert.equal(breathe(s), breathe(s));
  assert.equal(breathe(s), "Hiring eats your week. Yupcha runs it without you.");
});

test("empty / whitespace-only stays empty", () => {
  assert.equal(breathe(""), "");
  assert.equal(breathe("   "), "");
});

{
  "name": "kino-web",
  "version": "0.1.0",
  "private": true,
  "description": "Web product surface for the Kino video studio — the four SAAS_ROADMAP §3 trust gates over src/pipeline.",
  "scripts": {
    "dev": "next dev --port 3000",
    "build": "next build",
    "start": "next start --port 3000",
    "lint": "next lint"
  },
  "dependencies": {
    "next": "15.1.6",
    "react": "19.2.3",
    "react-dom": "19.2.3"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "@types/react": "19.2.7",
    "@types/react-dom": "^19.0.0",
    "typescript": "5.9.3"
  }
}

/**
 * heuristic.ts — the KEYLESS HEURISTIC DIRECTOR.
 *
 * `heuristicDirect(brandKit, goal)` → a validated `VideoSpec`, with **NO network
 * and NO LLM**. It deterministically assembles the frozen conversion template
 * (SAAS_ROADMAP §2) from a brand kit:
 *
 *   Hook (pain-led, never a logo) → ProductShot (first screen asset)
 *     → up to 3 FeatureBeat → Stats (marked unverified) → optional Proof
 *     → CTA (url).
 *
 * It is the free-tier, offline fallback for `direct()` (`director.ts`): same
 * input/output contract, same guarantees, but the *template* — not a model — is
 * the brain. Because the template is fixed and on-token by construction, the
 * output is ALWAYS schema-valid AND anti-slop-lint-clean for any reasonable kit
 * (the same gates `direct()` runs are asserted here in tests).
 *
 * Design rules (CLAUDE.md / ENGINE_DESIGN §2):
 *  - PURE + DETERMINISTIC. No `Date.now`, no `Math.random`, no I/O, no clock.
 *    Same `(brandKit, goal)` in → byte-identical `VideoSpec` out.
 *  - Assembles the frozen design system; never styles it. Preset is *selected*
 *    via the locked brand→preset binding (`src/design`); palette is threaded as
 *    DATA from the kit; motion/transition come from the chosen preset bundle.
 *  - Obeys every narrative rule so `validateSceneRefs` + `lintSpec` pass: ≤1
 *    Hook (first), ≤1 CTA (last), ≤1 Proof, ≤4 FeatureBeat; colors are PaletteKey
 *    references, never raw hex; screen/region keys are stills, never clips.
 *
 * Touches ONLY this file. Reuses `src/spec` (contract + lint), `src/design`
 * (preset binding + bundles), `src/ingest` (palette luminance), and the
 * `DirectorBrandKit` / `DirectorGoal` shapes from `director.ts` (type-only) —
 * it never edits `director.ts` / `providers.ts`.
 */
import { z } from "zod";

import {
  VideoSpec,
  type Palette,
  type Preset,
  type Motion,
} from "../spec";
import {
  preset as presetBundle,
  defaultPresetFor,
  gateBrandStyle,
  type Brand,
  type TransitionKind,
} from "../design";
import { parseColor, luminance, DEFAULT_PALETTE } from "../ingest";

import type { DirectorBrandKit, DirectorGoal } from "./director";

/* -------------------------------------------------------------------------- */
/*  Public re-exports (the heuristic director shares the director's I/O shape) */
/* -------------------------------------------------------------------------- */

export type { DirectorBrandKit, DirectorGoal } from "./director";

/* -------------------------------------------------------------------------- */
/*  Brand / preset selection                                                   */
/* -------------------------------------------------------------------------- */

/**
 * Map a brand kit to one of the shipped `Brand` ids when its name/url clearly
 * names a house brand, so the locked `BRAND_PRESETS` binding applies verbatim.
 * Returns `undefined` for any other ("arbitrary") brand — those fall through to
 * the palette-luminance heuristic below.
 */
function detectBrand(kit: DirectorBrandKit): Brand | undefined {
  const hay = `${kit.name ?? ""} ${kit.url ?? ""} ${kit.id ?? ""}`.toLowerCase();
  if (hay.includes("yupcha")) return "yupcha";
  if (hay.includes("resubird")) return "resubird";
  return undefined;
}

/**
 * Is a palette's background dark? Deterministic luminance test (reuses the
 * ingest color math). A dark field reads cinematic/agentic; a light field reads
 * editorial/warm — exactly the §4 brand→preset split.
 */
function isDarkPalette(palette: Palette): boolean {
  const rgb = parseColor(palette.bg);
  // No parseable bg → treat as dark (the safe default register, matching the
  // ingest `DEFAULT_PALETTE`, which is dark).
  if (!rgb) return true;
  return luminance(rgb) < 0.4;
}

/**
 * A trustworthy swatch, or the matching `DEFAULT_PALETTE` fallback. The ingest
 * pipeline always emits hex/rgb (`buildPalette`), so a swatch `parseColor` can't
 * read is a degraded/hand-rolled kit — we substitute the safe default for THAT
 * key so the threaded palette is always `zColor()`-valid and the spec parses.
 * Keeps the heuristic total for any reasonable kit (it never throws on a stray
 * swatch); a valid swatch is passed through byte-for-byte (no styling).
 */
function safeSwatch(value: string, key: keyof typeof DEFAULT_PALETTE): string {
  if (typeof value === "string" && parseColor(value) !== null) return value;
  const fallback = DEFAULT_PALETTE[key];
  return typeof fallback === "string" ? fallback : DEFAULT_PALETTE.accent;
}

/** Whether `p` is a valid preset id (defends `goal.preset` against junk). */
function isPreset(p: unknown): p is Preset {
  return (
    p === "minimal-mono" ||
    p === "gradient-glass" ||
    p === "editorial" ||
    p === "dark-cinematic"
  );
}

/**
 * Pick exactly ONE preset for the whole video (never mix — §4).
 *
 * Precedence:
 *  1. an explicit, valid `goal.preset` override;
 *  2. the locked `BRAND_PRESETS` default when the kit names a house brand;
 *  3. a palette-luminance heuristic for any other brand — dark bg →
 *     `dark-cinematic`, light bg → `editorial` (the two flagship registers).
 */
function pickPreset(
  kit: DirectorBrandKit,
  goal: DirectorGoal,
  palette: Palette,
): Preset {
  if (isPreset(goal.preset)) return goal.preset;

  const brand = detectBrand(kit);
  if (brand) return defaultPresetFor(brand);

  return isDarkPalette(palette) ? "dark-cinematic" : "editorial";
}

/**
 * Build the threaded `Palette` from the kit, substituting the safe default for
 * any swatch that is not a parseable color. Threaded as DATA — valid swatches
 * pass through unchanged; the gradientText pair is dropped if either stop is bad
 * (rather than emit a half-valid tuple).
 */
function buildSafePalette(kit: DirectorBrandKit): Palette {
  const p = kit.palette;
  const palette: Palette = {
    bg: safeSwatch(p.bg, "bg"),
    surface: safeSwatch(p.surface, "surface"),
    text: safeSwatch(p.text, "text"),
    textDim: safeSwatch(p.textDim, "textDim"),
    accent: safeSwatch(p.accent, "accent"),
  };
  if (p.accent2 !== undefined) palette.accent2 = safeSwatch(p.accent2, "accent2");
  if (
    p.gradientText !== undefined &&
    parseColor(p.gradientText[0]) !== null &&
    parseColor(p.gradientText[1]) !== null
  ) {
    palette.gradientText = [p.gradientText[0], p.gradientText[1]];
  }
  return palette;
}

/* -------------------------------------------------------------------------- */
/*  Voiceover                                                                   */
/* -------------------------------------------------------------------------- */

/** OmniVoice profile ids (CLAUDE.md — treated as examples / config, not magic). */
const VO_PROFILE_HELPDESK = "fd085cf0";
const VO_PROFILE_LUXE = "feat_20_the_luxe";

/**
 * The cinematic presets swap to the "Luxe" voice (deeper, slower) per §5; the
 * flat/utility presets stay on the default "Helpdesk" profile.
 */
function voProfileFor(p: Preset): string {
  return p === "dark-cinematic" ? VO_PROFILE_LUXE : VO_PROFILE_HELPDESK;
}

/* -------------------------------------------------------------------------- */
/*  Copy bank — pure helpers over the kit's ranked copy candidates             */
/* -------------------------------------------------------------------------- */

/** A normalized copy line: collapsed whitespace, trimmed, non-empty. */
function cleanLine(s: string): string {
  return s.replace(/\s+/g, " ").trim();
}

/**
 * The kit's copy bank as clean, de-duplicated, non-empty lines in rank order.
 * `brandKit.copy` is already salience-ranked by the ingest module; we only
 * normalize + de-dupe (case-insensitive), preserving order.
 */
function copyBank(kit: DirectorBrandKit): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const c of kit.copy ?? []) {
    const line = cleanLine(c.text ?? "");
    if (line.length < 2) continue;
    const key = line.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(line);
  }
  return out;
}

/** Ensure a string ends with sentence punctuation (for tidy VO/caption text). */
function asSentence(s: string): string {
  const t = cleanLine(s);
  if (!t) return t;
  return /[.!?]$/.test(t) ? t : `${t}.`;
}

/**
 * Pull the line at `idx` from the bank, falling back to `fallback` when the bank
 * is too short. Keeps the assembler total — every slot always gets real copy.
 */
function bankAt(bank: string[], idx: number, fallback: string): string {
  return bank[idx] ?? fallback;
}

/* -------------------------------------------------------------------------- */
/*  Asset selection                                                            */
/* -------------------------------------------------------------------------- */

/** A still asset key that is never a video clip (lint: `screen-is-still`). */
const VIDEO_KEY =
  /(?:\.(?:mp4|mov|webm|m4v|avi|mkv|gif))(?:$|[?#])|(?:^|[/_\-.])(?:video|clip|recording|offthreadvideo|reel)(?:$|[/_\-.])/i;

const isStillKey = (key: string): boolean => key.length > 0 && !VIDEO_KEY.test(key);

/**
 * The ordered list of usable STILL asset keys from the kit's screens. The ingest
 * module already orders screens hero/og/screenshot-first, so index 0 is the best
 * hero shot. Video-like keys are filtered out so the `screen-is-still` lint can
 * never trip. When the kit has no usable screens we synthesize a single
 * placeholder still key (deterministic, brand-scoped) so ProductShot/FeatureBeat
 * always have a valid still to point at.
 */
function stillKeys(kit: DirectorBrandKit): string[] {
  const keys = (kit.screens ?? [])
    .map((s) => s.key)
    .filter((k): k is string => typeof k === "string" && isStillKey(k));
  if (keys.length > 0) return keys;
  // Deterministic placeholder — a still slot, never a clip.
  return [`${kit.id}/hero`];
}

/* -------------------------------------------------------------------------- */
/*  Feature beats — derived from copy, capped at 3 (≤4 by rule, 3 per the §2    */
/*  template), sharing one layout by construction.                             */
/* -------------------------------------------------------------------------- */

/** lucide-react icon names cycled across feature beats / callouts (kebab-case). */
const FEATURE_ICONS = ["zap", "sparkles", "shield-check", "gauge"] as const;

/**
 * Short, brand-NEUTRAL benefit tails appended to each FeatureBeat's *narration*
 * (vo.text only — the on-screen `label`/`caption` props are untouched). They give
 * the read fuller sentences instead of staccato three-word fragments, and they
 * lift total narration over the launch-cut word FLOOR (`validateSceneRefs`) so an
 * auto-assembled keyless cut lands ~24–32s instead of a 14s blip. Indexed to the
 * default `FEATURE_ICONS` (zap→speed, sparkles→polish, shield-check→reliability)
 * so the spoken framing matches the beat's own iconography. No stat, no claim, no
 * fabricated proof — pure benefit register. Deterministic: a fixed table.
 */
const FEATURE_VO_TAILS = [
  "Fast where it counts.",
  "Polished and ready to ship.",
  "Reliable every single time.",
] as const;

/**
 * A narration-only tail for the ProductShot that frames the hero as doing the
 * end-to-end work. Spoken, not shown (the headline prop stays the brand's own
 * copy line). Helps the cut clear the word floor with grounded, claim-free copy.
 */
const PRODUCT_VO_TAIL = "Built to handle the busywork, end to end.";

/* -------------------------------------------------------------------------- */
/*  The heuristic director                                                     */
/* -------------------------------------------------------------------------- */

/**
 * Assemble a lint-clean, schema-valid `VideoSpec` from a brand kit + goal with
 * NO model and NO network. Deterministic and total: returns a parsed `VideoSpec`
 * for any reasonable kit (it throws only if the assembled object somehow fails
 * `VideoSpec.parse`, which the construction below makes structurally impossible
 * — the parse is the fail-closed safety net).
 */
export function heuristicDirect(
  brandKit: DirectorBrandKit,
  goal: DirectorGoal = {},
): VideoSpec {
  /* --- Palette: threaded as DATA (no styling); bad swatches → safe default. */
  const palette = buildSafePalette(brandKit);
  const hasAccent2 = palette.accent2 !== undefined;

  const chosenPreset = pickPreset(brandKit, goal, palette);
  const bundle = presetBundle(chosenPreset);
  const motion: Motion = bundle.motion;
  const profile = voProfileFor(chosenPreset);

  // Transition: the preset's default, which is by definition within its allowed
  // (≤2) set — so the look stays on-token.
  const transitionKind: TransitionKind = bundle.transition.default;

  const bank = copyBank(brandKit);
  const stills = stillKeys(brandKit);
  const brandName = cleanLine(brandKit.name ?? "") || "your product";

  /* --- S1 Hook — pain-led, ≤2 lines, never a logo. ----------------------- */
  // Lead with the goal angle when given; else the brand's top copy line; always
  // resolve into the product as the answer.
  const angle = goal.angle ? cleanLine(goal.angle) : undefined;
  const hookLead = angle ?? bankAt(bank, 0, `${brandName} should be effortless.`);
  const hookAnswer = `Meet ${brandName}.`;
  const hookLines = [cleanLine(hookLead), hookAnswer].filter(
    (l) => l.length > 0,
  );
  const hookScene = {
    id: "hook",
    component: "Hook" as const,
    props: { lines: hookLines.length ? hookLines : [hookAnswer] },
    vo: {
      text: asSentence(`${hookLead} ${hookAnswer}`),
      profile,
    },
  };

  /* --- S2 ProductShot — first screen asset; the hero shot. --------------- */
  const productLine = bankAt(bank, 1, `${brandName} does the work for you.`);
  const callouts: {
    title: string;
    sub?: string;
    icon: string;
    anchor: "tl" | "tr" | "bl" | "br";
    accent: "accent" | "accent2" | "text";
  }[] = [
    {
      title: cleanLine(bankAt(bank, 2, "Built for speed")),
      icon: FEATURE_ICONS[0],
      anchor: "tr",
      accent: "accent",
    },
    {
      title: cleanLine(bankAt(bank, 3, "On your terms")),
      icon: FEATURE_ICONS[1],
      anchor: "bl",
      // accent2 is optional in the palette — only reference it when present, else
      // fall back to a guaranteed key so the callout always resolves a color.
      accent: hasAccent2 ? "accent2" : "text",
    },
  ];
  const productScene = {
    id: "product",
    component: "ProductShot" as const,
    props: {
      kicker: brandName,
      headline: asSentence(productLine),
      screen: stills[0],
      layout: "single" as const,
      tilt: 6,
      callouts,
    },
    vo: { text: asSentence(`${productLine} ${PRODUCT_VO_TAIL}`), profile },
  };

  /* --- S3..S5 FeatureBeat — up to 3, sharing one layout. ----------------- */
  // Draw beats from copy lines after the ones used by hook/product; pair each
  // with a still (cycled) and a shared-family icon. Capped at 3 (≤4 by rule).
  const FEATURE_COUNT = 3;
  const featureScenes = [];
  for (let i = 0; i < FEATURE_COUNT; i++) {
    const copyIdx = 4 + i;
    const label = cleanLine(
      bankAt(bank, copyIdx, `Feature ${i + 1}`),
    );
    const caption = asSentence(
      bankAt(bank, copyIdx, `${brandName} handles it end to end.`),
    );
    // Skip a beat only if there is genuinely no distinct copy AND we already have
    // enough narrative; but to stay deterministic+total we always emit beats with
    // a real label/caption (the fallbacks above guarantee non-empty strings).
    featureScenes.push({
      id: `feature-${i + 1}`,
      component: "FeatureBeat" as const,
      props: {
        label: label || `Feature ${i + 1}`,
        region: stills[(i + 1) % stills.length],
        caption,
        earcon: bundle.sound.kind === "tick" ? "tick" : "whoosh",
      },
      // Narration is the caption plus a brand-neutral benefit tail (vo only) so
      // the read is a full sentence and the cut clears the launch word floor.
      vo: {
        text: asSentence(`${caption} ${FEATURE_VO_TAILS[i % FEATURE_VO_TAILS.length]}`),
        profile,
      },
    });
  }

  /* --- S6 Stats — examples by default (verified:false → "e.g." affordance). */
  const statsScene = {
    id: "stats",
    component: "Stats" as const,
    props: {
      items: [
        {
          to: 90,
          suffix: "%",
          decimals: 0,
          label: "faster than before",
          // Unverified: heuristic has no sourced metric → renders as an example.
          verified: false,
        },
        {
          to: 3,
          suffix: "x",
          decimals: 0,
          label: "more done per week",
          verified: false,
        },
      ],
    },
    vo: {
      text: asSentence(
        `Teams move dramatically faster with ${brandName}`,
      ),
      profile,
    },
  };

  /* --- S7 Proof (optional) — one quote, real attribution, when copy exists. */
  // Only include a Proof when the bank has a spare line we can attribute; the
  // template makes Proof optional (≤1) so omitting it is always valid.
  const proofCandidate = bank[4 + FEATURE_COUNT];
  const proofScene = proofCandidate
    ? {
        id: "proof",
        component: "Proof" as const,
        props: {
          quote: asSentence(cleanLine(proofCandidate)),
          attribution: brandName,
        },
        vo: {
          text: asSentence(cleanLine(proofCandidate)),
          profile,
        },
      }
    : undefined;

  /* --- S8 CTA — wordmark + one action + url; always LAST. ----------------- */
  const url = ctaUrl(brandKit);
  const ctaScene = {
    id: "cta",
    component: "CTA" as const,
    props: {
      headline: asSentence(bankAt(bank, 0, `Get started with ${brandName}`)),
      url,
    },
    vo: {
      text: asSentence(`Get started with ${brandName} at ${spoken(url)}`),
      profile,
    },
  };

  /* --- Assemble in conversion order; parse as the fail-closed safety net. - */
  const scenes = [
    hookScene,
    productScene,
    ...featureScenes,
    statsScene,
    ...(proofScene ? [proofScene] : []),
    ctaScene,
  ];

  const raw: z.input<typeof VideoSpec> = {
    version: 1,
    format: goal.format ?? "16:9",
    preset: chosenPreset,
    motion,
    palette,
    brandKitId: brandKit.id,
    transitions: { kind: transitionKind, durationInFrames: 15 },
    scenes,
  };

  // Parsing applies schema defaults and GUARANTEES a contract-valid result; the
  // assembler is built to never trip this, but it is the fail-closed net.
  const parsed = VideoSpec.parse(raw);
  // House-brand style gate (CD R2 P2): warm ResuBird's palette off the scraped
  // periwinkle + keep the preset inside the locked allow-list. No-op for any
  // non-house brand.
  const brandHint = `${brandKit.name ?? ""} ${brandKit.url ?? ""} ${brandKit.id ?? ""}`;
  return gateBrandStyle(parsed, brandHint);
}

/* -------------------------------------------------------------------------- */

/* -------------------------------------------------------------------------- */
/*  Small URL helpers (pure)                                                    */
/* -------------------------------------------------------------------------- */

/**
 * Derive the CTA url/host from the kit. Prefers the kit's `url` host; falls back
 * to a name-derived dotcom. Returned as a bare host (no scheme) to match the
 * sample's `"yupcha.com"` style.
 */
function ctaUrl(kit: DirectorBrandKit): string {
  const raw = cleanLine(kit.url ?? "");
  if (raw) {
    try {
      const u = new URL(raw.includes("://") ? raw : `https://${raw}`);
      return u.hostname.replace(/^www\./, "");
    } catch {
      /* fall through to name-derived */
    }
  }
  const slug = cleanLine(kit.name ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "");
  return slug ? `${slug}.com` : "example.com";
}

/** Render a host for speech ("yupcha.com" → "yupcha dot com"). */
function spoken(host: string): string {
  return host.replace(/\./g, " dot ");
}

/**
 * providers.ts — provider-agnostic LLM access for the DIRECTOR.
 *
 * The brain does two small *structured* jobs (emit `VideoSpec`, refine VO copy)
 * — NO codegen. The *validator* (`src/spec` + the director's repair loop), not
 * the model, is the quality gate, which is why a free-tier model suffices.
 *
 * One interface — `LlmProvider.complete({ system, user, jsonSchema })` — hides
 * four provider transports behind it:
 *
 *   - gemini      (default) — Gemini native generateContent with
 *                             `responseMimeType: application/json` +
 *                             `responseSchema` (JSON-schema mode).
 *   - groq        — OpenAI-compatible chat/completions, `response_format`
 *                   json_schema (Llama 3.3 70B — fast, for interactive re-specs).
 *   - openrouter  — OpenAI-compatible gateway (A/B model swap).
 *   - ollama      — local `/api/chat`, `format` = the JSON schema.
 *
 * Provider is chosen by `process.env.LLM_PROVIDER`; keys come from env. All
 * transports use `fetch` (no heavy SDK). Construction never touches the network;
 * a request only fires when `complete()` is awaited.
 *
 * Determinism note (CLAUDE.md / ENGINE_DESIGN §2): nothing here feeds render
 * motion — this is the *brain*, upstream of the `VideoSpec` contract. It may do
 * I/O. The deterministic-`t` rule applies downstream, to the renderer.
 */

/* -------------------------------------------------------------------------- */
/*  Public interface                                                          */
/* -------------------------------------------------------------------------- */

/**
 * A JSON Schema document (draft-7-ish) — the same shape `z.toJSONSchema`
 * produces in `src/spec/registry.ts`. Kept structural so we never import the
 * runtime zod object here; the director passes the schema in.
 */
export type JsonSchema = Record<string, unknown>;

/** A single structured-output request. */
export interface CompleteRequest {
  /** System / instruction prompt (allowed scenes, rules, the contract). */
  system: string;
  /** User content (brand kit + goal, or a repair message). */
  user: string;
  /**
   * The JSON schema the model MUST conform to. Providers that support native
   * schema-constrained decoding (gemini, groq, openrouter, ollama) are handed
   * this directly; it is also the contract the director re-validates against.
   */
  jsonSchema: JsonSchema;
  /**
   * Optional decode controls. Defaults bias toward determinism (low temp) since
   * we want stable, re-validatable structured output, not creative variance.
   */
  temperature?: number;
  maxOutputTokens?: number;
  /** Optional abort signal (caller timeout / cancellation). */
  signal?: AbortSignal;
}

/** The provider-agnostic completion interface. */
export interface LlmProvider {
  /** Stable provider id (for logs / error messages). */
  readonly id: LlmProviderId;
  /**
   * Run one structured completion. Returns the raw text the model emitted
   * (expected to be a JSON document); the director parses + validates it. Throws
   * `LlmError` on transport / HTTP / empty-response failure.
   */
  complete(req: CompleteRequest): Promise<string>;
}

export type LlmProviderId =
  | "gemini"
  | "groq"
  | "openrouter"
  | "ollama"
  | "cerebras";

/** The set of provider ids `LLM_PROVIDER` may select. */
export const PROVIDER_IDS: readonly LlmProviderId[] = [
  "gemini",
  "groq",
  "openrouter",
  "ollama",
  "cerebras",
] as const;

/** Raised on any provider transport failure (network, HTTP, empty body). */
export class LlmError extends Error {
  constructor(
    message: string,
    /** Which provider failed. */
    readonly provider: LlmProviderId,
    /** HTTP status when the failure was an HTTP error. */
    readonly status?: number,
  ) {
    super(message);
    this.name = "LlmError";
  }
}

/** Raised at selection time when env config is missing/invalid. */
export class LlmConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "LlmConfigError";
  }
}

/* -------------------------------------------------------------------------- */
/*  Env helpers                                                               */
/* -------------------------------------------------------------------------- */

/** Minimal env reader. Trims; treats blank/whitespace as absent. */
function env(name: string): string | undefined {
  const raw = (globalThis as { process?: { env?: Record<string, string | undefined> } })
    .process?.env?.[name];
  if (raw == null) return undefined;
  const v = raw.trim();
  return v.length ? v : undefined;
}

/** First non-empty env var among `names`. */
function envAny(...names: string[]): string | undefined {
  for (const n of names) {
    const v = env(n);
    if (v) return v;
  }
  return undefined;
}

/** Resolve the global `fetch`, or throw a clear config error. */
function resolveFetch(injected?: typeof fetch): typeof fetch {
  const f = injected ?? (globalThis as { fetch?: typeof fetch }).fetch;
  if (!f) {
    throw new LlmConfigError(
      "no global fetch available; pass opts.fetchImpl or run on Node >=18",
    );
  }
  return f;
}

/**
 * Shared options every concrete provider accepts. `fetchImpl` is injectable so
 * the director's tests can drive providers without a live network (the task's
 * ".env is empty, do NOT call the API live" constraint is satisfied by simply
 * never invoking `complete()` against a real endpoint).
 */
export interface ProviderOptions {
  apiKey?: string;
  baseUrl?: string;
  model?: string;
  fetchImpl?: typeof fetch;
  /** Per-request timeout (ms). Layered under any caller-supplied signal. */
  timeoutMs?: number;
}

const DEFAULT_TIMEOUT_MS = 60_000;
const DEFAULT_TEMPERATURE = 0.2;
const DEFAULT_MAX_TOKENS = 4096;

/**
 * Combine a caller `AbortSignal` with a timeout into one signal + cleanup.
 * Avoids `AbortSignal.any`/`timeout` (not in `lib: ["es2015"]`); hand-rolled and
 * deterministic in shape.
 */
function withTimeout(
  timeoutMs: number,
  caller?: AbortSignal,
): { signal: AbortSignal; done: () => void } {
  const controller = new AbortController();
  const onAbort = () => controller.abort();
  if (caller) {
    if (caller.aborted) controller.abort();
    else caller.addEventListener("abort", onAbort);
  }
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return {
    signal: controller.signal,
    done: () => {
      clearTimeout(timer);
      if (caller) caller.removeEventListener("abort", onAbort);
    },
  };
}

/** Shared POST-JSON helper with timeout + uniform error wrapping. */
async function postJson(
  id: LlmProviderId,
  fetchImpl: typeof fetch,
  url: string,
  headers: Record<string, string>,
  body: unknown,
  timeoutMs: number,
  callerSignal: AbortSignal | undefined,
): Promise<unknown> {
  const { signal, done } = withTimeout(timeoutMs, callerSignal);
  let res: Response;
  try {
    res = await fetchImpl(url, {
      method: "POST",
      headers: { "content-type": "application/json", ...headers },
      body: JSON.stringify(body),
      signal,
    });
  } catch (err) {
    const aborted = (err as { name?: string }).name === "AbortError";
    throw new LlmError(
      aborted
        ? `${id}: request aborted (timeout ${timeoutMs}ms or caller cancel)`
        : `${id}: network error — ${(err as Error).message}`,
      id,
    );
  } finally {
    done();
  }

  if (!res.ok) {
    const detail = await res.text().catch(() => "");
    throw new LlmError(
      `${id}: HTTP ${res.status} ${res.statusText}${
        detail ? ` — ${detail.slice(0, 400)}` : ""
      }`,
      id,
      res.status,
    );
  }

  try {
    return await res.json();
  } catch (err) {
    throw new LlmError(`${id}: response was not JSON — ${(err as Error).message}`, id);
  }
}

/** Pull a string at a dotted/indexed path; undefined if any hop is missing. */
function dig(obj: unknown, path: (string | number)[]): unknown {
  let cur: unknown = obj;
  for (const key of path) {
    if (cur == null || typeof cur !== "object") return undefined;
    cur = (cur as Record<string | number, unknown>)[key];
  }
  return cur;
}

/* -------------------------------------------------------------------------- */
/*  Gemini (default) — native JSON-schema mode                                */
/* -------------------------------------------------------------------------- */

/**
 * Gemini via the public Generative Language REST API. Uses
 * `generationConfig.responseMimeType = "application/json"` and `responseSchema`
 * so the model is constrained to emit schema-valid JSON (JSON-schema mode).
 *
 * Keys (first match wins): `GEMINI_API_KEY` (task convention) → `GOOGLE_AI_API_KEY`
 * → `GOOGLE_API_KEY` (the repo `.env` uses `GOOGLE_AI_API_KEY`).
 */
export class GeminiProvider implements LlmProvider {
  readonly id = "gemini" as const;
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly model: string;
  private readonly fetchImpl: typeof fetch;
  private readonly timeoutMs: number;

  constructor(opts: ProviderOptions = {}) {
    this.apiKey =
      opts.apiKey ??
      envAny("GEMINI_API_KEY", "GOOGLE_AI_API_KEY", "GOOGLE_API_KEY") ??
      "";
    this.baseUrl = (
      opts.baseUrl ??
      env("GEMINI_BASE_URL") ??
      "https://generativelanguage.googleapis.com/v1beta"
    ).replace(/\/+$/, "");
    this.model = opts.model ?? env("GEMINI_MODEL") ?? "gemini-2.5-flash";
    this.fetchImpl = resolveFetch(opts.fetchImpl);
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  }

  async complete(req: CompleteRequest): Promise<string> {
    if (!this.apiKey) {
      throw new LlmConfigError("gemini: missing GEMINI_API_KEY (or GOOGLE_AI_API_KEY)");
    }
    const url =
      `${this.baseUrl}/models/${encodeURIComponent(this.model)}:generateContent` +
      `?key=${encodeURIComponent(this.apiKey)}`;

    const body = {
      systemInstruction: { role: "system", parts: [{ text: req.system }] },
      contents: [{ role: "user", parts: [{ text: req.user }] }],
      generationConfig: {
        responseMimeType: "application/json",
        responseSchema: toGeminiSchema(req.jsonSchema),
        temperature: req.temperature ?? DEFAULT_TEMPERATURE,
        maxOutputTokens: req.maxOutputTokens ?? DEFAULT_MAX_TOKENS,
      },
    };

    const json = await postJson(
      this.id,
      this.fetchImpl,
      url,
      {},
      body,
      this.timeoutMs,
      req.signal,
    );

    // Concatenate every text part of the first candidate.
    const parts = dig(json, ["candidates", 0, "content", "parts"]);
    let text = "";
    if (Array.isArray(parts)) {
      for (const p of parts) {
        const t = (p as { text?: unknown }).text;
        if (typeof t === "string") text += t;
      }
    }
    if (!text) {
      const block = dig(json, ["promptFeedback", "blockReason"]);
      throw new LlmError(
        `gemini: empty completion${block ? ` (blockReason: ${String(block)})` : ""}`,
        this.id,
      );
    }
    return text;
  }
}

/**
 * Gemini's `responseSchema` accepts a JSON-Schema-like subset but rejects some
 * keywords (`$schema`, `additionalProperties`, `$ref` definitions, `default`).
 * Deterministically strip the unsupported keys and inline nothing else — the
 * director already owns the authoritative validation, so the on-wire schema only
 * needs to *steer* decoding.
 */
export function toGeminiSchema(schema: JsonSchema): JsonSchema {
  const STRIP = new Set([
    "$schema",
    "$id",
    "$ref",
    "definitions",
    "$defs",
    "additionalProperties",
    "default",
    "const",
    "patternProperties",
  ]);
  const walk = (node: unknown): unknown => {
    if (Array.isArray(node)) return node.map(walk);
    if (node && typeof node === "object") {
      const src = node as Record<string, unknown>;
      const out: Record<string, unknown> = {};
      for (const k of Object.keys(src)) {
        if (STRIP.has(k)) continue;
        out[k] = walk(src[k]);
      }
      return out;
    }
    return node;
  };
  return walk(schema) as JsonSchema;
}

/* -------------------------------------------------------------------------- */
/*  OpenAI-compatible providers (groq, openrouter)                            */
/* -------------------------------------------------------------------------- */

/**
 * Shared transport for the OpenAI-compatible `chat/completions` shape. Both Groq
 * and OpenRouter speak it; they differ only in default base URL, env var names,
 * default model, and a couple of headers.
 */
abstract class OpenAICompatProvider implements LlmProvider {
  abstract readonly id: LlmProviderId;
  protected readonly apiKey: string;
  protected readonly baseUrl: string;
  protected readonly model: string;
  protected readonly fetchImpl: typeof fetch;
  protected readonly timeoutMs: number;

  protected constructor(apiKey: string, baseUrl: string, model: string, opts: ProviderOptions) {
    this.apiKey = apiKey;
    this.baseUrl = baseUrl.replace(/\/+$/, "");
    this.model = model;
    this.fetchImpl = resolveFetch(opts.fetchImpl);
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  }

  /** Extra headers (e.g. OpenRouter ranking headers). */
  protected extraHeaders(): Record<string, string> {
    return {};
  }

  async complete(req: CompleteRequest): Promise<string> {
    if (!this.apiKey) {
      throw new LlmConfigError(`${this.id}: missing API key`);
    }
    const body = {
      model: this.model,
      temperature: req.temperature ?? DEFAULT_TEMPERATURE,
      max_tokens: req.maxOutputTokens ?? DEFAULT_MAX_TOKENS,
      messages: [
        { role: "system", content: req.system },
        { role: "user", content: req.user },
      ],
      // OpenAI structured-output: a named json_schema. `strict` is left OFF —
      // the VideoSpec uses unions / defaults / min-max that the providers' strict
      // subset rejects, and the DIRECTOR re-validates the result anyway (the
      // validator, not the decoder, is the quality gate).
      response_format: {
        type: "json_schema",
        json_schema: {
          name: "VideoSpec",
          strict: false,
          schema: req.jsonSchema,
        },
      },
    };

    const json = await postJson(
      this.id,
      this.fetchImpl,
      `${this.baseUrl}/chat/completions`,
      { authorization: `Bearer ${this.apiKey}`, ...this.extraHeaders() },
      body,
      this.timeoutMs,
      req.signal,
    );

    const content = dig(json, ["choices", 0, "message", "content"]);
    if (typeof content !== "string" || !content) {
      const finish = dig(json, ["choices", 0, "finish_reason"]);
      throw new LlmError(
        `${this.id}: empty completion${finish ? ` (finish_reason: ${String(finish)})` : ""}`,
        this.id,
      );
    }
    return content;
  }
}

/** Groq — OpenAI-compatible; Llama 3.3 70B by default (fast, interactive). */
export class GroqProvider extends OpenAICompatProvider {
  readonly id = "groq" as const;
  constructor(opts: ProviderOptions = {}) {
    super(
      opts.apiKey ?? env("GROQ_API_KEY") ?? "",
      opts.baseUrl ?? env("GROQ_BASE_URL") ?? "https://api.groq.com/openai/v1",
      opts.model ?? env("GROQ_MODEL") ?? "llama-3.3-70b-versatile",
      opts,
    );
  }
}

/** OpenRouter — OpenAI-compatible gateway (A/B model swap). */
export class OpenRouterProvider extends OpenAICompatProvider {
  readonly id = "openrouter" as const;
  constructor(opts: ProviderOptions = {}) {
    super(
      opts.apiKey ?? env("OPENROUTER_API_KEY") ?? "",
      opts.baseUrl ?? env("OPENROUTER_BASE_URL") ?? "https://openrouter.ai/api/v1",
      opts.model ?? env("OPENROUTER_MODEL") ?? "meta-llama/llama-3.3-70b-instruct",
      opts,
    );
  }

  protected override extraHeaders(): Record<string, string> {
    // Optional attribution headers OpenRouter uses for ranking; harmless if unset.
    const h: Record<string, string> = {};
    const referer = env("OPENROUTER_REFERER") ?? env("OPENROUTER_SITE_URL");
    const title = env("OPENROUTER_TITLE");
    if (referer) h["HTTP-Referer"] = referer;
    if (title) h["X-Title"] = title;
    return h;
  }
}

/**
 * Cerebras — OpenAI-compatible `chat/completions` with native `json_schema`
 * structured output. Default model `gpt-oss-120b`: a strong reasoning model on a
 * generous, fast free tier (verified to honor the exact base-class body shape —
 * `max_tokens` + `json_schema` strict:false — and return schema-valid content).
 */
export class CerebrasProvider extends OpenAICompatProvider {
  readonly id = "cerebras" as const;
  constructor(opts: ProviderOptions = {}) {
    super(
      opts.apiKey ?? env("CEREBRAS_API_KEY") ?? "",
      opts.baseUrl ?? env("CEREBRAS_BASE_URL") ?? "https://api.cerebras.ai/v1",
      opts.model ?? env("CEREBRAS_MODEL") ?? "gpt-oss-120b",
      opts,
    );
  }
}

/* -------------------------------------------------------------------------- */
/*  Ollama (local) — /api/chat with `format` = JSON schema                     */
/* -------------------------------------------------------------------------- */

/**
 * Ollama local server. Recent Ollama accepts a JSON schema in `format` for
 * structured output; we pass the schema through and disable streaming so one
 * response object comes back. No API key needed.
 */
export class OllamaProvider implements LlmProvider {
  readonly id = "ollama" as const;
  private readonly baseUrl: string;
  private readonly model: string;
  private readonly fetchImpl: typeof fetch;
  private readonly timeoutMs: number;

  constructor(opts: ProviderOptions = {}) {
    this.baseUrl = (
      opts.baseUrl ??
      env("OLLAMA_BASE_URL") ??
      "http://127.0.0.1:11434"
    ).replace(/\/+$/, "");
    this.model = opts.model ?? env("OLLAMA_MODEL") ?? "llama3.3";
    this.fetchImpl = resolveFetch(opts.fetchImpl);
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  }

  async complete(req: CompleteRequest): Promise<string> {
    const body = {
      model: this.model,
      stream: false,
      format: req.jsonSchema,
      options: { temperature: req.temperature ?? DEFAULT_TEMPERATURE },
      messages: [
        { role: "system", content: req.system },
        { role: "user", content: req.user },
      ],
    };

    const json = await postJson(
      this.id,
      this.fetchImpl,
      `${this.baseUrl}/api/chat`,
      {},
      body,
      this.timeoutMs,
      req.signal,
    );

    const content = dig(json, ["message", "content"]);
    if (typeof content !== "string" || !content) {
      throw new LlmError("ollama: empty completion", this.id);
    }
    return content;
  }
}

/* -------------------------------------------------------------------------- */
/*  Factory                                                                    */
/* -------------------------------------------------------------------------- */

const FACTORIES: Record<LlmProviderId, (o: ProviderOptions) => LlmProvider> = {
  gemini: (o) => new GeminiProvider(o),
  groq: (o) => new GroqProvider(o),
  openrouter: (o) => new OpenRouterProvider(o),
  ollama: (o) => new OllamaProvider(o),
  cerebras: (o) => new CerebrasProvider(o),
};

/** Normalize an arbitrary env string to a known provider id, or `undefined`. */
function parseProviderId(raw: string | undefined): LlmProviderId | undefined {
  if (!raw) return undefined;
  const v = raw.trim().toLowerCase().replace(/[\s_-]+/g, "");
  // Accept a few aliases (the repo `.env` historically used `google_ai`).
  if (v === "gemini" || v === "google" || v === "googleai") return "gemini";
  if (v === "groq") return "groq";
  if (v === "openrouter") return "openrouter";
  if (v === "ollama") return "ollama";
  if (v === "cerebras") return "cerebras";
  return undefined;
}

/**
 * Build a provider, choosing by `process.env.LLM_PROVIDER` (default `gemini`).
 * Construction never hits the network; pass `opts.fetchImpl` to inject a fetch
 * for tests so nothing calls a real API.
 *
 * Falls back to `LLM_DEFAULT_PROVIDER` (the name the repo `.env` actually sets)
 * before defaulting to gemini, so the wiring works with the existing env file.
 */
export function llm(opts: ProviderOptions = {}): LlmProvider {
  const raw = env("LLM_PROVIDER") ?? env("LLM_DEFAULT_PROVIDER");
  const id = parseProviderId(raw) ?? "gemini";
  // An explicit, unrecognized LLM_PROVIDER is a config error (fail loud), but a
  // missing one is fine (default applies).
  if (env("LLM_PROVIDER") && !parseProviderId(env("LLM_PROVIDER"))) {
    throw new LlmConfigError(
      `LLM_PROVIDER="${raw}" is not one of ${PROVIDER_IDS.join(", ")}`,
    );
  }
  return FACTORIES[id](opts);
}

/**
 * crawl.ts — Playwright (chromium) brand ingest.
 *
 * Given a URL, capture: full-page screenshot, an area-weighted color sample,
 * font-family names in use, logo (header img / og:image / favicon), hero / og
 * image, and the salient headline / value-prop copy.
 *
 * Design rules honored:
 *  - Cache by hash(url): a second crawl of the same URL is a disk read.
 *  - Respect robots.txt best-effort (fetch + parse; honor a matching Disallow).
 *  - Degrade gracefully when blocked / on error — always return a usable
 *    (possibly partial) RawCrawl, never throw to the caller for normal failures.
 *  - Nothing here feeds motion. `capturedAt` is provenance only. No Math.random.
 */

import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import * as path from "node:path";
import * as os from "node:os";

import type { Browser, Page } from "playwright";

import { normalizeBrandKit, type BrandKit, type RawCrawl } from "./brandkit";

/* ──────────────────────────────── options ────────────────────────────────── */

export type CrawlOptions = {
  /** Cache root. Default: <os.tmpdir>/yupcha-ingest-cache. */
  cacheDir?: string;
  /** Force a fresh crawl, ignoring (but refreshing) cache. */
  noCache?: boolean;
  /** Honor robots.txt. Default true (best-effort). */
  respectRobots?: boolean;
  /** Per-page navigation timeout in ms. Default 20000. */
  timeoutMs?: number;
  /** Viewport. Default 1440×900 desktop. */
  viewport?: { width: number; height: number };
  /** Device-pixel-ratio for captures. Default 2 (retina-crisp product stills). */
  deviceScaleFactor?: number;
  /** Max section screenshots to capture by scrolling. Default 4. */
  maxSectionShots?: number;
  /** Max copy nodes to sample. Default 40. */
  maxCopyNodes?: number;
  /** Identify ourselves honestly to the origin. */
  userAgent?: string;
};

const DEFAULTS = {
  respectRobots: true,
  timeoutMs: 20_000,
  viewport: { width: 1440, height: 900 },
  deviceScaleFactor: 2,
  maxSectionShots: 4,
  maxCopyNodes: 40,
  userAgent:
    "Mozilla/5.0 (compatible; YupchaBrandBot/1.0; +https://yupcha.com/bot)",
};

/**
 * Browser-context init shim, injected via `addInitScript` BEFORE any page or
 * `page.evaluate` script runs. When this module is bundled with esbuild/tsx
 * (keepNames on), our in-page functions are rewritten to call `__name(fn,"…")`
 * and class fields to `__publicField(...)` — helpers that don't exist in the
 * page. Without this shim every extractor throws `__name is not defined` and we
 * silently fall back to 0 copy / default palette. Passed as a STRING so it is
 * never itself rewritten by the bundler.
 */
const EVAL_SHIM_SRC =
  "(()=>{var g=globalThis;" +
  "if(typeof g.__name==='undefined')g.__name=function(f){return f;};" +
  "if(typeof g.__publicField==='undefined')g.__publicField=function(o,k,v){" +
  "Object.defineProperty(o,k,{enumerable:true,configurable:true,writable:true,value:v});return v;};" +
  "})();";

/** Stable cache key for a URL: sha256 of its normalized form, first 16 hex. */
export function hashUrl(url: string): string {
  const norm = normalizeUrlForHash(url);
  return createHash("sha256").update(norm).digest("hex").slice(0, 16);
}

/** Normalize a URL for hashing: lowercase host, drop fragment + trailing slash. */
function normalizeUrlForHash(url: string): string {
  try {
    const u = new URL(url.includes("://") ? url : `https://${url}`);
    u.hash = "";
    u.hostname = u.hostname.toLowerCase();
    let s = u.toString();
    if (s.endsWith("/")) s = s.slice(0, -1);
    return s;
  } catch {
    return url.trim().toLowerCase();
  }
}

function cacheRoot(opts: CrawlOptions): string {
  return opts.cacheDir ?? path.join(os.tmpdir(), "yupcha-ingest-cache");
}

/* ──────────────────────────── public entrypoints ─────────────────────────── */

/**
 * Crawl `url` and return a normalized, typed BrandKit. Cached by hash(url).
 * Never throws for ordinary failures — returns a degraded BrandKit instead.
 */
export async function ingest(
  url: string,
  options: CrawlOptions = {},
): Promise<BrandKit> {
  const opts = { ...DEFAULTS, ...options };
  const id = hashUrl(url);
  const dir = path.join(cacheRoot(opts), id);

  if (!opts.noCache) {
    const cached = await readCachedKit(dir);
    if (cached) return cached;
  }

  const raw = await crawl(url, opts);
  const kit = normalizeBrandKit(raw, id);
  await writeCachedKit(dir, kit);
  return kit;
}

/**
 * Low-level crawl: returns the RawCrawl (un-normalized). Exposed for callers
 * that want to re-normalize without re-fetching. Caches the raw payload too.
 */
export async function crawl(
  url: string,
  options: CrawlOptions = {},
): Promise<RawCrawl> {
  const opts = { ...DEFAULTS, ...options };
  const target = url.includes("://") ? url : `https://${url}`;
  const id = hashUrl(url);
  const dir = path.join(cacheRoot(opts), id);
  await fs.mkdir(dir, { recursive: true });

  const notes: string[] = [];
  const capturedAt = new Date().toISOString();

  // Robots best-effort gate.
  if (opts.respectRobots) {
    const allowed = await robotsAllows(target, opts.userAgent);
    if (allowed === false) {
      notes.push("robots.txt disallows this path; returning degraded crawl.");
      return degraded(target, notes, capturedAt);
    }
    if (allowed === null) notes.push("robots.txt unreadable; proceeding best-effort.");
  }

  let browser: Browser | null = null;
  try {
    browser = await launchChromium(opts.userAgent);
  } catch (e) {
    notes.push(`chromium launch failed (${errMsg(e)}); returning metadata-only crawl.`);
    return await metadataOnly(target, opts, notes, capturedAt);
  }

  try {
    const ctx = await browser.newContext({
      viewport: opts.viewport,
      userAgent: opts.userAgent,
      // Allow self-signed / local dev certs (e.g. a local https://…:3002 app),
      // so ingest can scrape a developer's own running instance, not just public
      // sites. Ingest is a read-only scrape; cert strictness adds no safety here.
      ignoreHTTPSErrors: true,
      // Retina capture: 2× device pixels → crisp product stills for the
      // ProductShot screen slot. Screenshots are physical-pixel, so a 1440-wide
      // viewport yields a 2880-wide PNG. CSS px in measurements stay unchanged.
      deviceScaleFactor: opts.deviceScaleFactor ?? 2,
      // Reduce motion so a screenshot is a stable frame, not mid-animation.
      reducedMotion: "reduce",
    });

    // Bundler-immunity shim. tsx/esbuild rewrites our in-page `page.evaluate`
    // arrow/named functions to call a `__name(fn,"…")` helper (keepNames). That
    // helper does NOT exist in the browser context, so EVERY extractor threw
    // `ReferenceError: __name is not defined` — the real cause of "0 copy /
    // default palette". Define a no-op shim (and a `__publicField` for class-
    // field downleveling) before any page or evaluate script runs.
    await ctx.addInitScript(EVAL_SHIM_SRC);

    const page = await ctx.newPage();

    let finalUrl = target;
    try {
      const resp = await page.goto(target, {
        // Wait for the JS app to render, not just the HTML doc. SPAs paint
        // nothing at domcontentloaded; "load" + a networkidle settle below gives
        // hydration time to typeset real copy and lay out the product UI.
        waitUntil: "load",
        timeout: opts.timeoutMs,
      });
      finalUrl = page.url() || target;
      if (resp && resp.status() >= 400) {
        notes.push(`navigation returned HTTP ${resp.status()}; capturing what loaded.`);
      }
      // Full-render settle: let late CSS/fonts/XHR finish, then explicitly wait
      // for web-fonts and trigger lazy content so screenshots are complete.
      await page
        .waitForLoadState("networkidle", { timeout: Math.min(8000, opts.timeoutMs) })
        .catch(() => notes.push("network did not idle; captured early."));
      await settleRender(page).catch((e) =>
        notes.push(`render settle incomplete (${errMsg(e)}).`),
      );
    } catch (e) {
      notes.push(`navigation failed (${errMsg(e)}); attempting partial capture.`);
    }

    const meta = await extractMeta(page).catch((e) => {
      notes.push(`meta extraction failed (${errMsg(e)}).`);
      return emptyMeta();
    });

    const colors = await sampleColors(page).catch((e) => {
      notes.push(`color sampling failed (${errMsg(e)}).`);
      return [] as RawCrawl["colors"];
    });

    const fonts = await sampleFonts(page).catch((e) => {
      notes.push(`font sampling failed (${errMsg(e)}).`);
      return [] as RawCrawl["fonts"];
    });

    const copy = await sampleCopy(page, opts.maxCopyNodes).catch((e) => {
      notes.push(`copy extraction failed (${errMsg(e)}).`);
      return [] as RawCrawl["copy"];
    });

    // Screenshots: capture MULTIPLE high-res stills so the ProductShot screen
    // slot has real product imagery, not one flat full-page strip:
    //   1. hero      — the top fold (viewport-framed), the primary product UI
    //   2. screenshot — the full-page capture (context / fallback)
    //   3. section-N — key sections discovered by scrolling (features, etc.)
    const images: RawCrawl["images"] = [];
    const dsf = opts.deviceScaleFactor ?? 2;
    const vp = await page.viewportSize();

    // 1. Hero — the above-the-fold frame at natural scroll position.
    try {
      await page.evaluate(() => window.scrollTo(0, 0)).catch(() => undefined);
      const heroPath = path.join(dir, "hero.png");
      await page.screenshot({ path: heroPath, fullPage: false, animations: "disabled" });
      images.push({
        src: finalUrl,
        path: heroPath,
        role: "hero",
        width: vp ? vp.width * dsf : undefined,
        height: vp ? vp.height * dsf : undefined,
      });
    } catch (e) {
      notes.push(`hero screenshot failed (${errMsg(e)}).`);
    }

    // 2. Full-page screenshot (context + fallback).
    const shotPath = path.join(dir, "screenshot.png");
    try {
      await page.screenshot({ path: shotPath, fullPage: true, animations: "disabled" });
      images.push({
        src: finalUrl,
        path: shotPath,
        role: "screenshot",
        width: vp ? vp.width * dsf : undefined,
        height: vp ? vp.height * dsf : undefined,
      });
    } catch (e) {
      notes.push(`full-page screenshot failed (${errMsg(e)}).`);
    }

    // 3. Section shots — find major content sections and frame each one.
    // Sites with scroll-triggered (IntersectionObserver) reveals paint a section
    // only once it has actually entered the viewport. Jumping straight to a far
    // target right after the full-page screenshot (which reset scroll to top)
    // races the reveal → blank stills. So we scroll MONOTONICALLY DOWN, stepping
    // through the targets in order with a settle at each, so every section is
    // scrolled INTO view (triggering its reveal) before we capture it.
    try {
      const sections = await findSections(page, opts.maxSectionShots);
      let kept = 0;
      for (let i = 0; i < sections.length; i++) {
        const s = sections[i];
        const secPath = path.join(dir, `section-${kept + 1}.png`);
        try {
          await scrollIntoViewSettled(page, s.scrollY);
          // Re-measure: bail if, after settling, the viewport is still mostly
          // empty (lazy content never arrived) so we never emit a blank still.
          const dense = await viewportHasContent(page);
          if (!dense) continue;
          await page.screenshot({ path: secPath, fullPage: false, animations: "disabled" });
          images.push({
            src: finalUrl,
            path: secPath,
            role: "image",
            width: vp ? vp.width * dsf : undefined,
            height: vp ? vp.height * dsf : undefined,
          });
          kept++;
        } catch {
          /* one bad section must not abort the rest */
        }
      }
      await page.evaluate(() => window.scrollTo(0, 0)).catch(() => undefined);
    } catch (e) {
      notes.push(`section screenshots failed (${errMsg(e)}).`);
    }

    // Resolve + download logo + hero/og images into the cache dir.
    const logos = await resolveLogos(page, finalUrl, meta, dir).catch((e) => {
      notes.push(`logo resolution failed (${errMsg(e)}).`);
      return [] as RawCrawl["logos"];
    });

    if (meta.ogImage) {
      const p = await download(page, absUrl(meta.ogImage, finalUrl), dir, "og").catch(
        () => undefined,
      );
      images.push({ src: absUrl(meta.ogImage, finalUrl), path: p, role: "og" });
    }

    const heroSrc = await findHero(page).catch(() => undefined);
    if (heroSrc) {
      const abs = absUrl(heroSrc, finalUrl);
      const p = await download(page, abs, dir, "hero").catch(() => undefined);
      images.push({ src: abs, path: p, role: "hero" });
    }

    await ctx.close().catch(() => undefined);

    const raw: RawCrawl = {
      url: target,
      finalUrl,
      title: meta.title,
      siteName: meta.siteName,
      colors,
      fonts,
      logos,
      images,
      copy,
      blocked: false,
      notes,
      capturedAt,
    };
    await writeRaw(dir, raw);
    return raw;
  } catch (e) {
    notes.push(`crawl aborted (${errMsg(e)}); returning degraded crawl.`);
    return degraded(target, notes, capturedAt);
  } finally {
    await browser?.close().catch(() => undefined);
  }
}

/* ─────────────────────────────── browser ─────────────────────────────────── */

async function launchChromium(userAgent: string): Promise<Browser> {
  // Lazy import so the module loads even where Playwright isn't installed yet
  // (e.g. type-checking in the parallel build before the integrator installs).
  const { chromium } = await import("playwright");
  void userAgent; // UA is applied per-context, not at launch.
  return chromium.launch({
    headless: true,
    args: [
      "--disable-blink-features=AutomationControlled",
      "--no-sandbox",
      "--disable-dev-shm-usage",
    ],
  });
}

/**
 * Full-render settle. After networkidle, (1) wait for web-fonts so typeset copy
 * is in its final face, (2) scroll the page top→bottom→top to trigger lazy
 * images / intersection-observer reveals, (3) wait one more short idle so the
 * newly-loaded assets paint. Deterministic w.r.t. the DOM; no Math.random, no
 * frame timing — this is capture-time provenance work, never motion.
 */
async function settleRender(page: Page): Promise<void> {
  // Fonts ready (bounded) — keeps screenshots from showing a fallback face.
  await page
    .evaluate(() => {
      const f = (document as unknown as { fonts?: { ready?: Promise<unknown> } }).fonts;
      return f?.ready ?? Promise.resolve();
    })
    .catch(() => undefined);

  // Trigger lazy-loaded content by walking the full scroll height, then return
  // to the top so the hero capture is from the natural starting position.
  await page
    .evaluate(async () => {
      const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
      const total = Math.max(
        document.body?.scrollHeight ?? 0,
        document.documentElement?.scrollHeight ?? 0,
      );
      const step = Math.max(1, window.innerHeight || 900);
      for (let y = 0; y <= total; y += step) {
        window.scrollTo(0, y);
        await sleep(60);
      }
      window.scrollTo(0, 0);
      await sleep(80);
    })
    .catch(() => undefined);

  // A brief final idle so lazy assets that just entered the DOM finish loading.
  await page
    .waitForLoadState("networkidle", { timeout: 3000 })
    .catch(() => undefined);
}

/**
 * Scroll DOWN to `targetY` in viewport-sized steps (never a single jump), so any
 * IntersectionObserver scroll-reveal between here and the target fires and paints
 * before we capture. Settles fonts/layout at the destination. Deterministic
 * w.r.t. the DOM — capture-time provenance work, never motion.
 */
async function scrollIntoViewSettled(page: Page, targetY: number): Promise<void> {
  await page
    .evaluate(async (target) => {
      const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
      const step = Math.max(1, Math.round((window.innerHeight || 900) * 0.9));
      let y = window.scrollY;
      // Step toward the target (handles both up and down) to trip reveals.
      while (Math.abs(window.scrollY - target) > step) {
        y += y < target ? step : -step;
        window.scrollTo(0, y);
        await sleep(40);
      }
      window.scrollTo(0, target);
      // Settle: let revealed content finish its enter + lazy images decode.
      await sleep(200);
    }, targetY)
    .catch(() => undefined);
  await page.waitForTimeout(100);
}

/**
 * True if the current viewport actually contains rendered, visible content
 * (enough opaque, on-screen, non-trivial elements). Guards against emitting a
 * blank still when lazy/revealed content failed to paint at this scroll offset.
 */
async function viewportHasContent(page: Page): Promise<boolean> {
  return page
    .evaluate(() => {
      const vh = window.innerHeight || 900;
      const vw = window.innerWidth || 1440;
      let area = 0;
      const els = Array.from(
        document.querySelectorAll(
          "h1,h2,h3,h4,p,li,img,svg,video,canvas,button,input,table,[class*='card']",
        ),
      ).slice(0, 600);
      for (const el of els) {
        const r = (el as HTMLElement).getBoundingClientRect();
        if (r.bottom <= 0 || r.top >= vh || r.width < 2 || r.height < 2) continue;
        const cs = getComputedStyle(el as HTMLElement);
        if (cs.visibility === "hidden" || cs.display === "none") continue;
        if (parseFloat(cs.opacity) < 0.4) continue; // mid-reveal / hidden
        const w = Math.min(r.right, vw) - Math.max(r.left, 0);
        const h = Math.min(r.bottom, vh) - Math.max(r.top, 0);
        if (w > 0 && h > 0) area += w * h;
      }
      // Require visible content covering ≥12% of the viewport.
      return area / (vw * vh) >= 0.12;
    })
    .catch(() => true); // on error, don't suppress the shot
}

/* ─────────────────────────── in-page extractors ──────────────────────────── */

type PageMeta = {
  title?: string;
  siteName?: string;
  ogImage?: string;
  favicon?: string;
  appleTouch?: string;
  description?: string;
};

function emptyMeta(): PageMeta {
  return {};
}

async function extractMeta(page: Page): Promise<PageMeta> {
  return page.evaluate(() => {
    const pick = (sel: string, attr: string): string | undefined => {
      const el = document.querySelector(sel);
      const v = el?.getAttribute(attr) ?? undefined;
      return v && v.trim() ? v.trim() : undefined;
    };
    return {
      title: document.title || undefined,
      siteName:
        pick('meta[property="og:site_name"]', "content") ??
        pick('meta[name="application-name"]', "content"),
      ogImage:
        pick('meta[property="og:image"]', "content") ??
        pick('meta[name="twitter:image"]', "content"),
      favicon:
        pick('link[rel="icon"]', "href") ??
        pick('link[rel="shortcut icon"]', "href"),
      appleTouch: pick('link[rel="apple-touch-icon"]', "href"),
      description: pick('meta[name="description"]', "content"),
    } as PageMeta;
  });
}

/**
 * Area-weighted color sample: walk visible elements, accumulate background /
 * text / border colors weighted by on-screen area. Deterministic given the DOM.
 */
async function sampleColors(page: Page): Promise<RawCrawl["colors"]> {
  return page.evaluate(() => {
    type Acc = { color: string; weight: number; source: string };
    const out = new Map<string, Acc>();
    const add = (color: string, weight: number, source: string) => {
      if (!color) return;
      const c = color.trim().toLowerCase();
      // Drop fully transparent + the default rgba(0,0,0,0).
      if (c === "transparent" || c === "rgba(0, 0, 0, 0)") return;
      const key = `${source}|${c}`;
      const prev = out.get(key);
      if (prev) prev.weight += weight;
      else out.set(key, { color: c, weight, source });
    };

    const vw = window.innerWidth || 1440;
    const vh = window.innerHeight || 900;
    const els = Array.from(document.body?.querySelectorAll("*") ?? []).slice(0, 4000);
    for (const el of els) {
      const r = (el as HTMLElement).getBoundingClientRect();
      if (r.width <= 0 || r.height <= 0) continue;
      // Only weight the on-screen portion (clamp to viewport).
      const w = Math.max(0, Math.min(r.right, vw) - Math.max(r.left, 0));
      const h = Math.max(0, Math.min(r.bottom, vh) - Math.max(r.top, 0));
      const area = w * h;
      if (area <= 0) continue;
      const norm = area / (vw * vh); // [0,1]
      const cs = getComputedStyle(el as HTMLElement);
      add(cs.backgroundColor, norm, "bg");
      // Text color weighted by area but only if the node has its own text.
      const hasText = Array.from(el.childNodes).some(
        (n) => n.nodeType === Node.TEXT_NODE && (n.textContent ?? "").trim().length > 0,
      );
      if (hasText) add(cs.color, norm * 0.6, "text");
      if (cs.borderTopWidth !== "0px") add(cs.borderTopColor, norm * 0.05, "border");
    }

    // Brand accent often lives ONLY on a small CTA — area-weighting misses it.
    // Sample button / primary-link fills directly with a strong source weight so
    // `pickAccents` (saturation × weight) surfaces the intentional brand color.
    const ctas = Array.from(
      document.querySelectorAll(
        "button, a[class*='btn'], a[class*='button'], [role='button'], a[class*='cta']",
      ),
    ).slice(0, 200);
    for (const el of ctas) {
      const r = (el as HTMLElement).getBoundingClientRect();
      if (r.width <= 0 || r.height <= 0) continue;
      if (r.top + window.scrollY > 2400) continue; // above-the-fold CTAs only
      const cs = getComputedStyle(el as HTMLElement);
      add(cs.backgroundColor, 0.5, "accent");
      if (cs.borderTopWidth !== "0px") add(cs.borderTopColor, 0.25, "accent");
    }

    // CSS custom properties on :root — brand systems name their accent here.
    const rootStyle = getComputedStyle(document.documentElement);
    for (const prop of [
      "--accent",
      "--color-primary",
      "--primary",
      "--brand",
      "--color-accent",
      "--brand-primary",
    ]) {
      const v = rootStyle.getPropertyValue(prop);
      if (v && v.trim()) add(v, 0.4, "accent");
    }
    return Array.from(out.values()) as RawCrawl["colors"];
  });
}

/** Font-family usage, weighted by visible text length. Deterministic. */
async function sampleFonts(page: Page): Promise<RawCrawl["fonts"]> {
  return page.evaluate(() => {
    const out = new Map<string, number>();
    const els = Array.from(document.body?.querySelectorAll("*") ?? []).slice(0, 4000);
    for (const el of els) {
      const text = Array.from(el.childNodes)
        .filter((n) => n.nodeType === Node.TEXT_NODE)
        .map((n) => (n.textContent ?? "").trim())
        .join("");
      if (!text) continue;
      const fam = getComputedStyle(el as HTMLElement).fontFamily;
      if (!fam) continue;
      out.set(fam, (out.get(fam) ?? 0) + text.length);
    }
    return Array.from(out.entries()).map(([family, weight]) => ({ family, weight }));
  });
}

/**
 * Salient copy: headline (largest text near top), subheads, value-prop, CTA
 * buttons. Classified by tag + font-size; returns font-size + top for ranking.
 */
async function sampleCopy(page: Page, maxNodes: number): Promise<RawCrawl["copy"]> {
  return page.evaluate((max) => {
    type Kind = "headline" | "subhead" | "value-prop" | "cta" | "meta";
    type C = { text: string; kind: Kind; fontSize: number; top: number };
    const out: C[] = [];
    const seen = new Set<string>();

    const classify = (el: Element, fontSize: number): Kind => {
      const tag = el.tagName.toLowerCase();
      const role = (el.getAttribute("role") ?? "").toLowerCase();
      if (tag === "h1" || fontSize >= 34) return "headline";
      if (tag === "h2" || tag === "h3" || fontSize >= 22) return "subhead";
      if (
        tag === "button" ||
        tag === "a" ||
        role === "button" ||
        (el as HTMLElement).className?.toString().toLowerCase().includes("btn")
      ) {
        return "cta";
      }
      if (tag === "p" || tag === "li" || tag === "span") return "value-prop";
      return "meta";
    };

    const candidates = Array.from(
      document.querySelectorAll(
        "h1,h2,h3,h4,p,li,span,a,button,[role='button'],strong,blockquote",
      ),
    ).slice(0, 2000);

    for (const el of candidates) {
      // Direct text only (avoid concatenating whole subtrees).
      const text = Array.from(el.childNodes)
        .filter((n) => n.nodeType === Node.TEXT_NODE)
        .map((n) => (n.textContent ?? "").replace(/\s+/g, " ").trim())
        .join(" ")
        .trim();
      if (!text || text.length < 2) continue;
      const key = text.toLowerCase();
      if (seen.has(key)) continue;

      const r = (el as HTMLElement).getBoundingClientRect();
      if (r.width <= 0 || r.height <= 0) continue;
      const cs = getComputedStyle(el as HTMLElement);
      if (cs.visibility === "hidden" || cs.display === "none") continue;
      const fontSize = parseFloat(cs.fontSize) || 16;

      seen.add(key);
      out.push({
        text,
        kind: classify(el, fontSize),
        fontSize,
        top: r.top + window.scrollY,
      });
      if (out.length >= max) break;
    }
    return out as C[];
  }, maxNodes);
}

/** Find the largest visible hero <img> in the upper region of the page. */
async function findHero(page: Page): Promise<string | undefined> {
  return page.evaluate(() => {
    let best: { src: string; area: number } | null = null;
    const imgs = Array.from(document.querySelectorAll("img")).slice(0, 300);
    for (const img of imgs) {
      const r = img.getBoundingClientRect();
      const top = r.top + window.scrollY;
      if (top > 1200) continue; // upper region only
      const area = r.width * r.height;
      if (area < 40_000) continue; // ignore icons/thumbs
      const src = img.currentSrc || img.src;
      if (!src) continue;
      if (!best || area > best.area) best = { src, area };
    }
    return best?.src;
  });
}

/**
 * Find major below-the-fold content sections to frame as screenshots. Picks
 * large, distinct full-width blocks (`section`, landmarks, big content divs)
 * past the first fold. For each, compute a `scrollY` that centers the section's
 * CONTENT (the bounding box of its meaningful descendants) in the viewport, and
 * SKIP sections that are mostly empty whitespace — those produced blank stills.
 * Deterministic given the DOM (sorted by `top`).
 */
async function findSections(
  page: Page,
  max: number,
): Promise<{ top: number; height: number; scrollY: number }[]> {
  return page.evaluate((maxN) => {
    const vh = window.innerHeight || 900;
    const vw = window.innerWidth || 1440;
    const maxScroll = Math.max(
      0,
      (document.documentElement?.scrollHeight ?? 0) - vh,
    );
    const cands = Array.from(
      document.querySelectorAll("section, main > div, [role='region'], article"),
    );
    const out: { top: number; height: number; scrollY: number; density: number }[] = [];

    for (const el of cands) {
      const r = (el as HTMLElement).getBoundingClientRect();
      const top = r.top + window.scrollY;
      if (top < vh * 0.8) continue;
      if (r.height < vh * 0.4) continue;
      if (r.width < vw * 0.5) continue;

      // Content box: union of rects of meaningful descendants (text, media,
      // controls). This collapses leading/trailing padding so we frame the
      // real content, and lets us measure how "full" the section is.
      let cTop = Infinity;
      let cBot = -Infinity;
      let filled = 0;
      const kids = el.querySelectorAll(
        "h1,h2,h3,h4,h5,p,li,img,svg,video,button,a,input,canvas,table,pre,code,figure,[class*='card']",
      );
      for (const k of Array.from(kids).slice(0, 400)) {
        const kr = (k as HTMLElement).getBoundingClientRect();
        if (kr.width <= 1 || kr.height <= 1) continue;
        const kt = kr.top + window.scrollY;
        cTop = Math.min(cTop, kt);
        cBot = Math.max(cBot, kt + kr.height);
        filled += Math.min(kr.width, vw) * Math.min(kr.height, vh);
      }
      const hasContent = cTop !== Infinity;
      const contentTop = hasContent ? cTop : top;
      const contentBot = hasContent ? cBot : top + r.height;
      const contentMid = (contentTop + contentBot) / 2;
      // Density = filled content area relative to one viewport. Skip sections
      // that are nearly empty (the blank-still cause).
      const density = filled / (vw * vh);
      if (density < 0.18) continue;

      // Center the content in the viewport, clamped to the scrollable range.
      const scrollY = Math.max(0, Math.min(maxScroll, Math.round(contentMid - vh / 2)));

      // Dedupe sections whose framed scroll target is within ~half a viewport.
      if (out.some((o) => Math.abs(o.scrollY - scrollY) < vh * 0.5)) continue;
      out.push({ top, height: r.height, scrollY, density });
    }
    out.sort((a, b) => a.top - b.top);
    return out.slice(0, maxN).map(({ top, height, scrollY }) => ({ top, height, scrollY }));
  }, max);
}

/* ──────────────────────────── logo resolution ────────────────────────────── */

async function resolveLogos(
  page: Page,
  finalUrl: string,
  meta: PageMeta,
  dir: string,
): Promise<RawCrawl["logos"]> {
  const logos: RawCrawl["logos"] = [];

  // Header wordmark: prefer an inline <svg> (crisp vector), else an <img>, both
  // scoped to <header>/[role=banner]/nav near the top-left. Returns either the
  // img src or a standalone SVG document string.
  const headerLogo = await page
    .evaluate(() => {
      const scopes = Array.from(
        document.querySelectorAll("header, [role='banner'], nav"),
      );

      // 1. Inline SVG wordmark — serialize to a standalone .svg document.
      // Score every plausible top-left SVG and keep the BEST, rather than the
      // first. A 12×12 nav glyph and the real wordmark both pass a boolean
      // "looksLogo" test; without scoring we grabbed the tiny icon. Score
      // rewards larger area + wordmark aspect (wider-than-tall) + explicit
      // logo class/aria, so the brand mark wins over decorative icons.
      let bestSvg:
        | { markup: string; w: number; h: number; score: number }
        | null = null;
      for (const scope of scopes) {
        const svgs = Array.from(scope.querySelectorAll("svg"));
        for (const svg of svgs) {
          const r = (svg as Element).getBoundingClientRect();
          if (r.width <= 0 || r.height <= 0) continue;
          if (r.top >= 200) continue;
          // Reject icon-sized marks and oversized illustrations.
          if (r.height < 14 || r.height > 96) continue;
          if (r.width < 16 || r.width > 480) continue;
          const cls = (svg.getAttribute("class") ?? "").toLowerCase();
          const aria = (svg.getAttribute("aria-label") ?? "").toLowerCase();
          const named =
            cls.includes("logo") ||
            aria.includes("logo") ||
            aria.includes("home") ||
            aria.includes(document.title.split(/[\s|—-]/)[0].toLowerCase());
          const topLeft = r.left < 400 && r.top < 160;
          if (!named && !topLeft) continue;
          const aspect = r.width / r.height; // wordmarks are wide
          let score = r.width * r.height; // bigger = more likely the mark
          if (aspect >= 2) score *= 1.8; // wordmark aspect
          else if (aspect < 1.2) score *= 0.5; // square = probably an icon
          if (named) score *= 1.6;
          if (r.left < 240) score *= 1.15; // far-left header slot
          if (bestSvg && score <= bestSvg.score) continue;
          let markup = svg.outerHTML;
          if (!/xmlns=/.test(markup)) {
            markup = markup.replace(
              /^<svg/i,
              '<svg xmlns="http://www.w3.org/2000/svg"',
            );
          }
          bestSvg = {
            markup,
            w: Math.round(r.width),
            h: Math.round(r.height),
            score,
          };
        }
      }
      if (bestSvg) {
        return {
          kind: "svg" as const,
          markup: bestSvg.markup,
          w: bestSvg.w,
          h: bestSvg.h,
        };
      }

      // 2. <img> wordmark.
      for (const scope of scopes) {
        const imgs = Array.from(scope.querySelectorAll("img"));
        for (const img of imgs) {
          const r = img.getBoundingClientRect();
          if (r.width <= 0 || r.height <= 0) continue;
          const cls = (img.getAttribute("class") ?? "").toLowerCase();
          const alt = (img.getAttribute("alt") ?? "").toLowerCase();
          const looksLogo =
            cls.includes("logo") ||
            alt.includes("logo") ||
            (r.top < 160 && r.left < 400 && r.height <= 80);
          if (looksLogo) return { kind: "img" as const, src: img.currentSrc || img.src };
        }
      }
      return undefined;
    })
    .catch(() => undefined);

  if (headerLogo?.kind === "svg" && headerLogo.markup) {
    try {
      const svgPath = path.join(dir, "logo.svg");
      await fs.writeFile(svgPath, headerLogo.markup, "utf8");
      logos.push({
        src: finalUrl,
        path: svgPath,
        kind: "svg",
        width: headerLogo.w,
        height: headerLogo.h,
      });
    } catch {
      /* best-effort */
    }
  } else if (headerLogo?.kind === "img" && headerLogo.src) {
    const abs = absUrl(headerLogo.src, finalUrl);
    const p = await download(page, abs, dir, "logo-header").catch(() => undefined);
    logos.push({ src: abs, path: p, kind: "header-img" });
  }

  if (meta.ogImage) {
    logos.push({ src: absUrl(meta.ogImage, finalUrl), kind: "og-image" });
  }
  if (meta.appleTouch) {
    const abs = absUrl(meta.appleTouch, finalUrl);
    const p = await download(page, abs, dir, "apple-touch").catch(() => undefined);
    logos.push({ src: abs, path: p, kind: "apple-touch-icon" });
  }
  // Favicon: explicit link, else conventional /favicon.ico.
  const favHref = meta.favicon ?? "/favicon.ico";
  const favAbs = absUrl(favHref, finalUrl);
  const favPath = await download(page, favAbs, dir, "favicon").catch(() => undefined);
  logos.push({ src: favAbs, path: favPath, kind: "favicon" });

  return logos;
}

/**
 * Download a remote asset through the page's request context (shares cookies /
 * UA / referer), writing to the cache dir. Returns the local path or throws.
 */
async function download(
  page: Page,
  url: string,
  dir: string,
  baseName: string,
): Promise<string | undefined> {
  if (!url || url.startsWith("data:")) return undefined;
  const resp = await page.request.get(url, { timeout: 10_000 });
  if (!resp.ok()) return undefined;
  const buf = await resp.body();
  if (!buf || buf.length === 0) return undefined;
  const ext = extFromContentType(resp.headers()["content-type"]) ?? extFromUrl(url) ?? "img";
  const file = path.join(dir, `${baseName}.${ext}`);
  await fs.writeFile(file, buf);
  return file;
}

/* ────────────────────────── robots best-effort ───────────────────────────── */

/**
 * Best-effort robots check. Returns:
 *   true  → allowed (or no rule)
 *   false → a matching Disallow blocks this path for our UA / '*'
 *   null  → robots.txt unreadable (treat as allowed, but note it)
 *
 * Minimal, dependency-free parser: honors User-agent groups for our token and
 * '*', longest-match Allow/Disallow precedence.
 */
export async function robotsAllows(
  targetUrl: string,
  userAgent: string,
): Promise<boolean | null> {
  let robotsTxt: string;
  let pathName: string;
  try {
    const u = new URL(targetUrl);
    pathName = u.pathname || "/";
    const robotsUrl = `${u.protocol}//${u.host}/robots.txt`;
    const res = await fetch(robotsUrl, {
      headers: { "user-agent": userAgent },
      // node fetch: bound the wait so a hung origin doesn't stall ingest.
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) return null;
    robotsTxt = await res.text();
  } catch {
    return null;
  }
  return evaluateRobots(robotsTxt, pathName, uaToken(userAgent));
}

/** Lowercased product token from a UA string (e.g. "yupchabrandbot"). */
function uaToken(userAgent: string): string {
  const m = userAgent.match(/([a-z][a-z0-9-]*bot)/i);
  return (m?.[1] ?? userAgent).toLowerCase();
}

/** Pure robots evaluator — exported for unit testing; no I/O. */
export function evaluateRobots(
  robotsTxt: string,
  pathName: string,
  token: string,
): boolean {
  const lines = robotsTxt.split(/\r?\n/).map((l) => l.replace(/#.*$/, "").trim());
  // Build agent → rules groups.
  type Rule = { allow: boolean; pattern: string };
  const groups: { agents: string[]; rules: Rule[] }[] = [];
  let current: { agents: string[]; rules: Rule[] } | null = null;
  let lastWasAgent = false;

  for (const line of lines) {
    if (!line) continue;
    const idx = line.indexOf(":");
    if (idx === -1) continue;
    const field = line.slice(0, idx).trim().toLowerCase();
    const value = line.slice(idx + 1).trim();

    if (field === "user-agent") {
      if (!current || !lastWasAgent) {
        current = { agents: [], rules: [] };
        groups.push(current);
      }
      current.agents.push(value.toLowerCase());
      lastWasAgent = true;
    } else if (field === "allow" || field === "disallow") {
      if (!current) {
        current = { agents: ["*"], rules: [] };
        groups.push(current);
      }
      current.rules.push({ allow: field === "allow", pattern: value });
      lastWasAgent = false;
    } else {
      lastWasAgent = false;
    }
  }

  // Select the most specific matching group: our token > '*'.
  const forToken = groups.find((g) => g.agents.includes(token));
  const forStar = groups.find((g) => g.agents.includes("*"));
  const group = forToken ?? forStar;
  if (!group) return true;

  // Longest-match precedence; on equal length, Allow wins (standard).
  let decision: { allow: boolean; len: number } | null = null;
  for (const rule of group.rules) {
    if (rule.pattern === "") continue; // empty Disallow = allow all
    if (matchesRobotsPattern(pathName, rule.pattern)) {
      const len = rule.pattern.length;
      if (!decision || len > decision.len || (len === decision.len && rule.allow)) {
        decision = { allow: rule.allow, len };
      }
    }
  }
  return decision ? decision.allow : true;
}

/** robots.txt path matching with `*` wildcard and `$` end-anchor. */
function matchesRobotsPattern(pathName: string, pattern: string): boolean {
  // Translate robots glob to a regex, escaping everything else.
  let anchored = false;
  let p = pattern;
  if (p.endsWith("$")) {
    anchored = true;
    p = p.slice(0, -1);
  }
  const re = p
    .split("*")
    .map((seg) => seg.replace(/[.+?^${}()|[\]\\]/g, "\\$&"))
    .join(".*");
  const rx = new RegExp("^" + re + (anchored ? "$" : ""));
  return rx.test(pathName);
}

/* ───────────────────────────── degraded paths ────────────────────────────── */

/** Fully-degraded crawl: no browser data, safe defaults downstream. */
function degraded(url: string, notes: string[], capturedAt: string): RawCrawl {
  return {
    url,
    finalUrl: url,
    colors: [],
    fonts: [],
    logos: [],
    images: [],
    copy: [],
    blocked: true,
    notes,
    capturedAt,
  };
}

/**
 * Metadata-only crawl (no chromium): fetch the HTML directly and regex out
 * title / og:image / favicon so we still return *something* useful when the
 * browser can't launch.
 */
async function metadataOnly(
  url: string,
  opts: typeof DEFAULTS,
  notes: string[],
  capturedAt: string,
): Promise<RawCrawl> {
  try {
    const res = await fetch(url, {
      headers: { "user-agent": opts.userAgent },
      signal: AbortSignal.timeout(opts.timeoutMs),
    });
    if (!res.ok) {
      notes.push(`metadata fetch HTTP ${res.status}.`);
      return degraded(url, notes, capturedAt);
    }
    const html = await res.text();
    const finalUrl = res.url || url;
    const grab = (re: RegExp): string | undefined => html.match(re)?.[1]?.trim();
    const title = grab(/<title[^>]*>([^<]+)<\/title>/i);
    const siteName = grab(
      /<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i,
    );
    const ogImage = grab(
      /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i,
    );
    const favicon = grab(
      /<link[^>]+rel=["'](?:shortcut )?icon["'][^>]+href=["']([^"']+)["']/i,
    );

    const images: RawCrawl["images"] = [];
    const logos: RawCrawl["logos"] = [];
    if (ogImage) {
      const abs = absUrl(ogImage, finalUrl);
      images.push({ src: abs, role: "og" });
      logos.push({ src: abs, kind: "og-image" });
    }
    logos.push({ src: absUrl(favicon ?? "/favicon.ico", finalUrl), kind: "favicon" });

    // Cheap headline harvest from <h1> tags.
    const copy: RawCrawl["copy"] = [];
    const h1 = grab(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.replace(/<[^>]+>/g, " ").trim();
    if (h1) copy.push({ text: h1, kind: "headline", fontSize: 40, top: 0 });
    if (siteName) copy.push({ text: siteName, kind: "meta", fontSize: 16, top: 0 });

    return {
      url,
      finalUrl,
      title,
      siteName,
      colors: [],
      fonts: [],
      logos,
      images,
      copy,
      blocked: false,
      notes,
      capturedAt,
    };
  } catch (e) {
    notes.push(`metadata-only fetch failed (${errMsg(e)}).`);
    return degraded(url, notes, capturedAt);
  }
}

/* ───────────────────────────────── cache ─────────────────────────────────── */

async function readCachedKit(dir: string): Promise<BrandKit | null> {
  try {
    const buf = await fs.readFile(path.join(dir, "brandkit.json"), "utf8");
    return JSON.parse(buf) as BrandKit;
  } catch {
    return null;
  }
}

async function writeCachedKit(dir: string, kit: BrandKit): Promise<void> {
  try {
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(path.join(dir, "brandkit.json"), JSON.stringify(kit, null, 2));
  } catch {
    // Cache write is best-effort; a failure must not break the crawl.
  }
}

async function writeRaw(dir: string, raw: RawCrawl): Promise<void> {
  try {
    await fs.writeFile(path.join(dir, "raw.json"), JSON.stringify(raw, null, 2));
  } catch {
    /* best-effort */
  }
}

/* ───────────────────────────────── utils ─────────────────────────────────── */

function absUrl(href: string, base: string): string {
  try {
    return new URL(href, base).toString();
  } catch {
    return href;
  }
}

function extFromContentType(ct?: string): string | undefined {
  if (!ct) return undefined;
  const t = ct.split(";")[0].trim().toLowerCase();
  const map: Record<string, string> = {
    "image/png": "png",
    "image/jpeg": "jpg",
    "image/jpg": "jpg",
    "image/webp": "webp",
    "image/svg+xml": "svg",
    "image/gif": "gif",
    "image/x-icon": "ico",
    "image/vnd.microsoft.icon": "ico",
    "image/avif": "avif",
  };
  return map[t];
}

function extFromUrl(url: string): string | undefined {
  const m = url.split("?")[0].match(/\.([a-z0-9]{2,5})$/i);
  return m?.[1]?.toLowerCase();
}

function errMsg(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}

