/* -------------------------------------------------------------------------- */
/*  Response extraction + validation                                          */
/* -------------------------------------------------------------------------- */

/**
 * Pull a JSON object out of a model response. Structured-output modes return raw
 * JSON, but a stray ```json fence or leading prose can sneak in — we slice from
 * the first `{` to its matching `}` (brace-balanced, string/escape aware) so a
 * tail comment doesn't break `JSON.parse`. Returns the parsed value or throws.
 */
export function extractJson(raw: string): unknown {
  const text = raw.trim();
  // Fast path: the whole thing is JSON.
  try {
    return JSON.parse(text);
  } catch {
    /* fall through to brace-slicing */
  }

  const start = text.indexOf("{");
  if (start === -1) throw new Error("no JSON object found in model output");

  let depth = 0;
  let inStr = false;
  let escaped = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inStr) {
      if (escaped) escaped = false;
      else if (ch === "\\") escaped = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') inStr = true;
    else if (ch === "{") depth++;
    else if (ch === "}") {
      depth--;
      if (depth === 0) {
        return JSON.parse(text.slice(start, i + 1));
      }
    }
  }
  throw new Error("unterminated JSON object in model output");
}

/**
 * Registry + narrative ref check. The discriminated union already guarantees
 * each scene's props match its component, so this enforces the invariants the
 * Zod schema cannot express:
 *   - every `component` is a real REGISTRY key (defense-in-depth);
 *   - scene ids are unique;
 *   - ≤1 Hook and it is first; ≤1 CTA and it is last; ≤1 Proof; ≤4 FeatureBeat;
 *   - `brandKitId` is present (it is, by schema, but we surface a clear message).
 *
 * Returns `[]` when valid, else a list of human-readable violations (fed back to
 * the model as the repair message).
 */
export function validateSceneRefs(spec: z.infer<typeof VideoSpec>): string[] {
  const errs: string[] = [];
  const valid = new Set<string>(SCENE_NAMES);

  const ids = new Set<string>();
  let hooks = 0;
  let ctas = 0;
  let proofs = 0;
  let features = 0;

  spec.scenes.forEach((scene, i) => {
    if (!valid.has(scene.component)) {
      errs.push(
        `scenes[${i}].component "${scene.component}" is not a registered scene ` +
          `(allowed: ${SCENE_NAMES.join(", ")})`,
      );
    }
    if (ids.has(scene.id)) errs.push(`scenes[${i}].id "${scene.id}" is duplicated`);
    ids.add(scene.id);

    if (scene.component === "Hook") {
      hooks++;
      if (i !== 0) errs.push(`Hook must be the FIRST scene (found at index ${i})`);
    }
    if (scene.component === "CTA") {
      ctas++;
      if (i !== spec.scenes.length - 1) {
        errs.push(`CTA must be the LAST scene (found at index ${i})`);
      }
    }
    if (scene.component === "Proof") proofs++;
    if (scene.component === "FeatureBeat") features++;
  });

  if (hooks > 1) errs.push(`at most ONE Hook scene is allowed (found ${hooks})`);
  if (ctas > 1) errs.push(`at most ONE CTA scene is allowed (found ${ctas})`);
  if (proofs > 1) errs.push(`at most ONE Proof scene is allowed (found ${proofs})`);
  if (features > 4) {
    errs.push(`at most FOUR FeatureBeat scenes are allowed (found ${features})`);
  }

  // WORD BUDGET — a FLOOR *and* a ceiling (CD R4 P0 — MANDATED). Duration is
  // derived from the MEASURED VO, so total narration is the one lever that pins
  // the cut's length. Two failure modes, both shipped to the judges:
  //   • OVER  — the 58s feature-march "dragged" (R3): a ceiling caps it.
  //   • UNDER — v4 came in at 34 words / 14.9s, "over before it lands" (R4): the
  //             model under-wrote and nothing rejected it. A FLOOR catches that.
  // The prompt asks for ~70–110 words / ~24–32s; we bracket that with hard
  // reject bounds (<60 too thin to land a launch story; >120 drags) so the model
  // can't ship a cut that is either too short or too long even when it ignores
  // the soft target. ~120 words ≈ 34s, ~60 words ≈ 18s at a deliberate read.
  const WORD_FLOOR = 60;
  const WORD_BUDGET = 120;
  let words = 0;
  for (const scene of spec.scenes) {
    const text = scene.vo?.text;
    if (typeof text === "string") {
      words += text.trim().split(/\s+/).filter(Boolean).length;
    }
  }
  if (words < WORD_FLOOR) {
    errs.push(
      `total narration is only ${words} words — a launch cut needs ~70–110 words ` +
        `(~24–32s); under ${WORD_FLOOR} it is over before it lands. Add a FeatureBeat ` +
        `or expand the vo.text lines into fuller sentences.`,
    );
  }
  if (words > WORD_BUDGET) {
    errs.push(
      `total narration is ${words} words — a punchy launch cut must stay under ` +
        `${WORD_BUDGET} words (~28–34s). Cut a scene or tighten the vo.text lines.`,
    );
  }

  return errs;
}

/** Format a zod error into a compact, model-readable issue list. */
function formatZodError(err: z.ZodError): string {
  return err.issues
    .map((iss) => {
      const path = iss.path.length
        ? iss.path.map((p) => String(p)).join(".")
        : "(root)";
      return `- ${path}: ${iss.message}`;
    })
    .join("\n");
}

/* -------------------------------------------------------------------------- */
/*  The director                                                              */
/* -------------------------------------------------------------------------- */

/** Tunables for `direct` (mostly for tests / provider injection). */
export interface DirectOptions {
  /** Provider to use. Defaults to `llm()` (env-selected). */
  provider?: LlmProvider;
  /** Max validation+repair attempts (total calls). Defaults to 3. */
  maxRepairs?: number;
  /** Decode temperature. Low by default for stable, re-validatable output. */
  temperature?: number;
  /** Abort signal threaded into every provider call. */
  signal?: AbortSignal;
}

/**
 * Build the initial user message: the brand kit + goal, plus the brandKitId and
 * palette the model must thread through unchanged.
 */
function buildUserMessage(brandKit: DirectorBrandKit, goal: DirectorGoal): string {
  const assetKeys = (brandKit.screens ?? []).map((s) => s.key);
  return JSON.stringify(
    {
      instruction:
        "Produce ONE VideoSpec JSON object for this brand and goal. Use " +
        "brandKitId and palette EXACTLY as given. Reference only the listed " +
        "assetKeys for screen/region/logos.",
      brandKitId: brandKit.id,
      palette: brandKit.palette,
      brand: {
        name: brandKit.name,
        url: brandKit.url,
        fonts: brandKit.fonts ?? [],
        voice: brandKit.voice,
        assetKeys,
        copyBank: (brandKit.copy ?? []).map((c) => c.text).slice(0, 24),
      },
      goal: {
        format: goal.format ?? "16:9",
        platform: goal.platform,
        angle: goal.angle,
        lengthSeconds: goal.lengthSeconds,
        preset: goal.preset,
        notes: goal.notes,
      },
    },
    null,
    0,
  );
}

/**
 * Direct a video: brand kit + goal → validated `VideoSpec`.
 *
 * Calls the provider, parses + validates, and on failure repairs by appending
 * the exact error to the user message and re-asking, up to `maxRepairs` total
 * attempts. Throws `SpecValidationError` (fail-closed) if all attempts fail —
 * the deterministic renderer is never handed an unvalidated spec.
 */
export async function direct(
  brandKit: DirectorBrandKit,
  goal: DirectorGoal = {},
  opts: DirectOptions = {},
): Promise<z.infer<typeof VideoSpec>> {
  const provider = opts.provider ?? llm();
  const maxRepairs = Math.max(1, opts.maxRepairs ?? 3);
  const system = buildDirectorPrompt();

  let user = buildUserMessage(brandKit, goal);
  const attempts: string[] = [];
  let lastRaw: string | undefined;

  for (let i = 0; i < maxRepairs; i++) {
    const raw = await provider.complete({
      system,
      user,
      jsonSchema: VIDEOSPEC_JSON_SCHEMA,
      temperature: opts.temperature,
      signal: opts.signal,
    });
    lastRaw = raw.slice(0, 4000);

    // 1) Extract + parse JSON.
    let parsedJson: unknown;
    try {
      parsedJson = extractJson(raw);
    } catch (err) {
      const reason = `attempt ${i + 1}: not parseable JSON — ${(err as Error).message}`;
      attempts.push(reason);
      user = repairMessage(user, `Your previous output was not valid JSON: ${(err as Error).message}`);
      continue;
    }

    // 2) Validate against the frozen contract.
    const result = VideoSpec.safeParse(parsedJson);
    if (!result.success) {
      const zodMsg = formatZodError(result.error);
      attempts.push(`attempt ${i + 1}: schema invalid\n${zodMsg}`);
      user = repairMessage(
        user,
        `Your previous output FAILED VideoSpec validation:\n${zodMsg}`,
      );
      continue;
    }

    // 3) Registry / narrative ref check.
    const refErrs = validateSceneRefs(result.data);
    if (refErrs.length) {
      const refMsg = refErrs.map((e) => `- ${e}`).join("\n");
      attempts.push(`attempt ${i + 1}: ref/narrative invalid\n${refMsg}`);
      user = repairMessage(
        user,
        `Your previous output broke narrative/asset rules:\n${refMsg}`,
      );
      continue;
    }

    // 4) Anti-slop lint (SAAS_ROADMAP §4). CRITICAL: lint the RAW object, not
    //    `result.data` — `VideoSpec.parse` silently STRIPS off-contract fields
    //    (`grain:0`, a per-scene `preset`/`motion` override, an OffthreadVideo
    //    `screen`, a >0.7 restraint dial), which is exactly the slop the lint
    //    exists to catch. Linting the stripped spec would pass everything.
    const lint = lintSpec(parsedJson as z.infer<typeof VideoSpec>);
    if (!lint.ok) {
      const lintMsg = lint.violations
        .map((v) => `- [${v.rule}] ${v.path}: ${v.message}`)
        .join("\n");
      attempts.push(`attempt ${i + 1}: anti-slop lint failed\n${lintMsg}`);
      user = repairMessage(
        user,
        `Your previous output FAILED the anti-slop guardrails:\n${lintMsg}`,
      );
      continue;
    }

    // 5) Stat-trust REGENERATION gate. The silent post-processor `gateStatTrust`
    //    can scrub a callout or demote a Stat, but it CANNOT edit a spoken
    //    `vo.text` mid-sentence or rescue an invented testimonial — those must be
    //    REGENERATED clean (CD R3 P0: the 0/3 disqualifier — fabricated social
    //    proof "50K+ / 4.9★ / 92% / Jane D., Verified customer" reached the
    //    screen AND the VO because captions/narration were an unguarded channel).
    const trustErrs = findTrustViolations(result.data);
    if (trustErrs.length) {
      const trustMsg = trustErrs.map((e) => `- ${e}`).join("\n");
      attempts.push(`attempt ${i + 1}: stat-trust violations\n${trustMsg}`);
      user = repairMessage(
        user,
        `Your previous output FABRICATED unverifiable social proof:\n${trustMsg}`,
      );
      continue;
    }

    // Valid + brandKit-consistent → gate stat-trust → gate brand-style → done.
    // `gateStatTrust` forces every Stats item to render as an unverified "e.g."
    // example, drops any callout that reads as a numeric claim, and drops an
    // unverifiable logo-wall proof — so a model-fabricated number/empty proof can
    // NEVER reach the screen as a hard, contradictable claim (CD: the
    // disqualifier — self-contradicting social proof). `gateBrandStyle` then
    // clamps a house brand back onto its locked preset + on-brand palette
    // (warms ResuBird off the scraped periwinkle).
    const brandHint = `${brandKit.name ?? ""} ${brandKit.url ?? ""} ${brandKit.id ?? ""}`;
    return gateBrandStyle(
      gateStatTrust(ensureBrandKitId(result.data, brandKit.id)),
      brandHint,
    );
  }

  throw new SpecValidationError(
    `director failed to produce a valid VideoSpec after ${maxRepairs} attempts`,
    attempts,
    lastRaw,
  );
}

/**
 * Append a repair instruction to the running user message. Keeps the original
 * brief at the top (so context isn't lost) and feeds the error back, asking for
 * corrected JSON only.
 */
function repairMessage(prevUser: string, errorBlock: string): string {
  return (
    prevUser +
    `\n\n--- REPAIR ---\n${errorBlock}\n` +
    "Return a corrected VideoSpec JSON object ONLY (no prose, no fences). " +
    "Fix exactly the issues above; keep everything else."
  );
}

/**
 * Guarantee the emitted spec's `brandKitId` matches the kit we directed for —
 * the model is instructed to thread it through, but we enforce it rather than
 * trust it (cheap, deterministic, prevents a mis-keyed render).
 */
function ensureBrandKitId(
  spec: z.infer<typeof VideoSpec>,
  brandKitId: string,
): z.infer<typeof VideoSpec> {
  if (spec.brandKitId === brandKitId) return spec;
  return { ...spec, brandKitId };
}

// Pacing helpers — make the read breathe instead of running wall-to-wall.
//
// Two independent levers, both off by default-safe values:
//
//  1. SENTENCE BREATHING (text level, pure): normalize a line so multi-sentence
//     copy carries clear terminal punctuation. OmniVoice keys its intra-line
//     pausing off punctuation, so this lengthens the natural pause between
//     sentences WITHOUT changing a single spoken word. Pure string→string.
//
//  2. LEAD-IN / TAIL SILENCE (audio level, ffmpeg): prepend/append a short pad
//     of real silence to a normalized clip so a line never butts hard against
//     the scene cut, and successive lines get an audible inter-line gap. This is
//     the audio counterpart to place.ts's frame `pad` (which only reserves
//     trailing frames in the layout; this puts actual silence in the wav).

import { spawn } from "node:child_process";

/**
 * Add gentle sentence breathing to a VO line. Pure: same input → same output.
 *
 * - Collapses runs of whitespace to single spaces and trims.
 * - Ensures the line ends in terminal punctuation (adds "." if it ends on a
 *   word) so the final clause resolves instead of being clipped flat.
 * - Guarantees a single space after sentence-final punctuation between
 *   sentences (so `…funnel.Let an agent…` → `…funnel. Let an agent…`), giving
 *   the engine a real sentence boundary to pause on.
 *
 * Does NOT add, remove, or reorder words — only whitespace/terminal punctuation,
 * so captions derived from the text stay faithful.
 */
export function breathe(text: string): string {
  let t = text.replace(/\s+/g, " ").trim();
  if (!t) return t;
  // Insert a space after sentence-final punctuation immediately followed by a
  // letter/number (a missing inter-sentence space), without touching decimals
  // like "9.0" (handled by requiring a following alphabetic char or capital).
  t = t.replace(/([.!?])([A-Za-z])/g, "$1 $2");
  // Ensure the line resolves with terminal punctuation.
  if (!/[.!?…,:;]$/.test(t)) t += ".";
  return t;
}

export interface PadSilenceOptions {
  /** Seconds of silence prepended before the clip. Default 0.18. */
  leadInSec?: number;
  /** Seconds of silence appended after the clip. Default 0.32. */
  tailSec?: number;
  /** Sample rate of the padding (matches loudnorm output). Default 48000. */
  sampleRate?: number;
  /** ffmpeg binary path. */
  ffmpegPath?: string;
}

export interface PadSilenceResult {
  outPath: string;
  /** Total seconds of silence added (lead-in + tail). */
  addedSeconds: number;
}

/**
 * Write `outPath` = leadIn-silence + `inPath` + tail-silence, preserving the
 * input's loudness (we pad with true silence; we do NOT re-run loudnorm, so the
 * I=-14 integrated loudness of the speech is unchanged — silence is excluded
 * from gated loudness). Rejects with ffmpeg stderr on failure.
 *
 * Uses ffmpeg `adelay` (lead-in) + `apad` (tail) in one pass. Deterministic:
 * silence is exact, so the padded wav is a pure function of the input + pads.
 */
export function padSilence(
  inPath: string,
  outPath: string,
  opts: PadSilenceOptions = {},
): Promise<PadSilenceResult> {
  const leadInSec = opts.leadInSec ?? 0.18;
  const tailSec = opts.tailSec ?? 0.32;
  const sampleRate = opts.sampleRate ?? 48_000;
  const bin = opts.ffmpegPath ?? "ffmpeg";

  if (inPath === outPath) {
    return Promise.reject(
      new Error("padSilence: inPath and outPath must differ"),
    );
  }
  if (leadInSec < 0 || tailSec < 0 || !Number.isFinite(leadInSec) || !Number.isFinite(tailSec)) {
    return Promise.reject(
      new Error(`padSilence: lead-in/tail must be finite >= 0, got ${leadInSec}/${tailSec}`),
    );
  }

  const leadMs = Math.round(leadInSec * 1000);
  // adelay delays ALL channels by leadMs; apad pads the tail with tailSec.
  const filter = `adelay=${leadMs}:all=1,apad=pad_dur=${tailSec}`;

  const args = [
    "-hide_banner",
    "-nostdin",
    "-y",
    "-i",
    inPath,
    "-af",
    filter,
    "-ar",
    String(sampleRate),
    "-c:a",
    "pcm_s16le",
    outPath,
  ];

  return new Promise<PadSilenceResult>((resolve, reject) => {
    const child = spawn(bin, args, { stdio: ["ignore", "ignore", "pipe"] });
    let stderr = "";
    child.stderr.on("data", (d: Buffer) => {
      stderr += d.toString();
    });
    child.on("error", (err) =>
      reject(new Error(`padSilence: failed to spawn ${bin}: ${err.message}`)),
    );
    child.on("close", (code) => {
      if (code === 0) resolve({ outPath, addedSeconds: leadInSec + tailSec });
      else reject(new Error(`padSilence: ffmpeg exited ${code}\n${stderr.slice(-1000)}`));
    });
  });
}

/**
 * POST /api/render  — Gate 4 (Render): the foregone conclusion.
 *
 * Two modes:
 *  - { spec, brandKit? }  → render the GATE-APPROVED spec verbatim (preferred —
 *    "what they approve is what renders"). Reuses `renderApprovedSpec`.
 *  - { url|assets|goal }   → full `generateVideo(input)` (plan→VO→render) for a
 *    one-shot path with no prior gates.
 *
 * Returns: { spec, videoUrl, stills, brandKit }. Keyless + VO-less still yields a
 * real (silent) mp4. The mp4 + stills are served via `/api/asset`.
 */
import { mkdir } from "node:fs/promises";
import { createHash } from "node:crypto";
import { join } from "node:path";

import { generateVideo, renderStoryboard } from "../../../lib/pipeline.server";
import { renderApprovedSpec } from "../../../lib/render.server";
import { WEB_STILLS_DIR, assetUrl } from "../../../lib/assets.server";
import type {
  VideoSpec,
  BrandKit,
  GenerateInput,
  RenderResponse,
} from "../../../lib/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 600;

export async function POST(req: Request): Promise<Response> {
  let body: GenerateInput & { spec?: VideoSpec; brandKit?: BrandKit };
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "invalid JSON body" }, { status: 400 });
  }

  try {
    // --- Mode A: render the approved spec verbatim. ----------------------
    if (body.spec) {
      const spec = body.spec;
      const { outPath } = await renderApprovedSpec(spec);
      const videoUrl = assetUrl(outPath);
      if (!videoUrl) throw new Error("rendered mp4 escaped the out/ tree");

      // Stills for the result view (cheap; reuses the stills gate path).
      const stills = await serveStills(spec);

      const res: RenderResponse = {
        spec,
        videoUrl,
        stills,
        brandKit: body.brandKit as BrandKit,
      };
      return Response.json(res, { status: 200 });
    }

    // --- Mode B: one-shot generate from input. ---------------------------
    if (!body.url && !(body.assets && body.assets.length)) {
      return Response.json(
        { error: "provide an approved spec, or a url/assets to generate from" },
        { status: 400 },
      );
    }
    const result = await generateVideo({
      url: body.url,
      assets: body.assets,
      goal: body.goal,
      brandKit: body.brandKit,
    });
    const videoUrl = assetUrl(result.outPath);
    if (!videoUrl) throw new Error("rendered mp4 escaped the out/ tree");
    const stills = await serveStills(result.spec);

    const res: RenderResponse = {
      spec: result.spec,
      videoUrl,
      stills,
      brandKit: result.brandKit,
    };
    return Response.json(res, { status: 200 });
  } catch (err) {
    const e = err as { message?: string; detail?: string };
    return Response.json(
      { error: e?.message ?? "render failed", detail: e?.detail },
      { status: 500 },
    );
  }
}

/**
 * Render the per-scene stills straight into `out/web/<hash>/` (so the asset route
 * can serve them) and return their browser URLs. Cheap (N screenshots, no encode)
 * and idempotent per spec hash.
 */
async function serveStills(spec: VideoSpec): Promise<string[]> {
  const hash = createHash("sha1")
    .update(JSON.stringify(spec))
    .digest("hex")
    .slice(0, 12);
  const dir = join(WEB_STILLS_DIR, hash);
  await mkdir(dir, { recursive: true });
  const { stills } = await renderStoryboard(spec, { outDir: dir });
  return stills
    .map((p) => assetUrl(p))
    .filter((u): u is string => u !== null);
}

/**
 * GET /api/asset?p=<out-relative-key>
 *
 * Streams a pipeline output (still PNG or rendered mp4) from the `out/` tree.
 * Confined to `out/` (traversal-hardened in `resolveAssetKey`). Supports HTTP
 * Range so the <video> player can scrub without downloading the whole file.
 */
import { stat, open } from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";

import { resolveAssetKey, contentTypeFor } from "../../../lib/assets.server";

/**
 * Wrap a FileHandle's bytes in a ReadableStream that EXPLICITLY closes the
 * handle when the stream finishes, errors, or is cancelled. `fh.readableWebStream()`
 * does NOT close the fd on its own; relying on GC to close it now throws a fatal
 * `ERR_INVALID_STATE` in modern Node, which would crash the server. Reading via
 * the handle and closing it here keeps the fd lifecycle deterministic.
 */
function closingStream(fh: FileHandle): ReadableStream<Uint8Array> {
  const src = fh.readableWebStream() as unknown as ReadableStream<Uint8Array>;
  const reader = src.getReader();
  let closed = false;
  const closeHandle = async () => {
    if (closed) return;
    closed = true;
    await fh.close().catch(() => {});
  };
  return new ReadableStream<Uint8Array>({
    async pull(controller) {
      try {
        const { done, value } = await reader.read();
        if (done) {
          controller.close();
          await closeHandle();
          return;
        }
        controller.enqueue(value);
      } catch (err) {
        await closeHandle();
        controller.error(err);
      }
    },
    async cancel() {
      await reader.cancel().catch(() => {});
      await closeHandle();
    },
  });
}

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(req: Request): Promise<Response> {
  const url = new URL(req.url);
  const key = url.searchParams.get("p") ?? "";
  const abs = resolveAssetKey(key);
  if (!abs) {
    return Response.json({ error: "invalid asset key" }, { status: 400 });
  }

  let size: number;
  try {
    const s = await stat(abs);
    if (!s.isFile()) throw new Error("not a file");
    size = s.size;
  } catch {
    return Response.json({ error: "asset not found" }, { status: 404 });
  }

  const contentType = contentTypeFor(abs);
  const range = req.headers.get("range");

  // Full-file response (stills, downloads, or no Range header).
  if (!range) {
    const fh = await open(abs, "r");
    const stream = closingStream(fh);
    return new Response(stream, {
      status: 200,
      headers: {
        "content-type": contentType,
        "content-length": String(size),
        "accept-ranges": "bytes",
        "cache-control": "no-store",
      },
    });
  }

  // Range response (video scrubbing). Parse `bytes=start-end`.
  const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  if (!m) {
    return new Response("invalid range", {
      status: 416,
      headers: { "content-range": `bytes */${size}` },
    });
  }
  let start = m[1] ? Number.parseInt(m[1], 10) : 0;
  let end = m[2] ? Number.parseInt(m[2], 10) : size - 1;
  if (Number.isNaN(start) || Number.isNaN(end) || start > end || end >= size) {
    return new Response("range not satisfiable", {
      status: 416,
      headers: { "content-range": `bytes */${size}` },
    });
  }
  start = Math.max(0, start);
  end = Math.min(end, size - 1);
  const chunkSize = end - start + 1;

  const fh = await open(abs, "r");
  const stream = closingStream(fh);
  // Slice via a transform: we read the whole web stream but only forward the
  // requested window. Simpler + robust for mp4 finals (a few MB).
  const sliced = sliceStream(stream, start, chunkSize);

  return new Response(sliced, {
    status: 206,
    headers: {
      "content-type": contentType,
      "content-length": String(chunkSize),
      "content-range": `bytes ${start}-${end}/${size}`,
      "accept-ranges": "bytes",
      "cache-control": "no-store",
    },
  });
}

/** Forward only `[offset, offset+length)` bytes of a byte ReadableStream. */
function sliceStream(
  source: ReadableStream,
  offset: number,
  length: number,
): ReadableStream {
  const reader = source.getReader();
  let pos = 0;
  let sent = 0;
  return new ReadableStream({
    async pull(controller) {
      while (sent < length) {
        const { done, value } = await reader.read();
        if (done) {
          controller.close();
          return;
        }
        const chunk = value as Uint8Array;
        const chunkStart = pos;
        const chunkEnd = pos + chunk.byteLength;
        pos = chunkEnd;
        if (chunkEnd <= offset) continue; // entirely before the window
        const from = Math.max(0, offset - chunkStart);
        const remaining = length - sent;
        const to = Math.min(chunk.byteLength, from + remaining);
        const piece = chunk.subarray(from, to);
        sent += piece.byteLength;
        controller.enqueue(piece);
        if (sent >= length) {
          controller.close();
          await reader.cancel().catch(() => {});
          return;
        }
        return;
      }
      controller.close();
    },
    async cancel() {
      await reader.cancel().catch(() => {});
    },
  });
}

/**
 * POST /api/outline  — Gate 2 (Outline): plan the STORY, no render.
 *
 * Body: { url?, assets?, goal?, brandKit? }  (the documented planOutline input)
 * Returns: { spec, brandKit }
 *
 * Runs server-side so any LLM key stays on the server. Keyless-safe: with no key
 * the pipeline uses the heuristic director; the response is identical in shape.
 */
import { planOutline } from "../../../lib/pipeline.server";
import type { GenerateInput, OutlineResponse } from "../../../lib/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 120;

export async function POST(req: Request): Promise<Response> {
  let body: GenerateInput;
  try {
    body = (await req.json()) as GenerateInput;
  } catch {
    return Response.json({ error: "invalid JSON body" }, { status: 400 });
  }

  if (!body.url && !body.brandKit && !(body.assets && body.assets.length)) {
    return Response.json(
      { error: "provide a url, assets, or a brandKit" },
      { status: 400 },
    );
  }

  try {
    const { spec, brandKit } = await planOutline({
      url: body.url,
      assets: body.assets,
      goal: body.goal,
      brandKit: body.brandKit,
    });
    const res: OutlineResponse = { spec, brandKit };
    return Response.json(res, { status: 200 });
  } catch (err) {
    return errorResponse(err);
  }
}

function errorResponse(err: unknown): Response {
  const e = err as { message?: string; detail?: string; attempts?: string[] };
  const detail =
    e?.detail ?? (Array.isArray(e?.attempts) ? e.attempts.join("\n") : undefined);
  return Response.json(
    { error: e?.message ?? "outline failed", detail },
    { status: 500 },
  );
}

/**
 * POST /api/storyboard  — Gate 3 (Storyboard): approve the LOOK.
 *
 * Body: { spec }  (the outline-approved VideoSpec)
 * Returns: { stills }  (browser URLs, one real keyframe per scene)
 *
 * Calls `renderStoryboard(spec, { outDir })` — the cheap, seconds-not-minutes
 * stills gate (CLAUDE.md: stills are the trusted surface; OffthreadVideo is
 * unreliable). Stills are written straight into `out/web/<hash>/` and served via
 * `/api/asset`. "What they approve is what renders."
 */
import { mkdir } from "node:fs/promises";
import { createHash } from "node:crypto";
import { join } from "node:path";

import { renderStoryboard } from "../../../lib/pipeline.server";
import { WEB_STILLS_DIR, assetUrl } from "../../../lib/assets.server";
import type { VideoSpec, StoryboardResponse } from "../../../lib/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 300;

export async function POST(req: Request): Promise<Response> {
  let body: { spec?: VideoSpec };
  try {
    body = (await req.json()) as { spec?: VideoSpec };
  } catch {
    return Response.json({ error: "invalid JSON body" }, { status: 400 });
  }
  if (!body.spec) {
    return Response.json({ error: "missing spec" }, { status: 400 });
  }
  const spec = body.spec;

  try {
    const hash = createHash("sha1")
      .update(JSON.stringify(spec))
      .digest("hex")
      .slice(0, 12);
    const dir = join(WEB_STILLS_DIR, hash);
    await mkdir(dir, { recursive: true });

    // Stills land directly under out/web/<hash>/ so the asset route can serve them.
    const { stills } = await renderStoryboard(spec, { outDir: dir });

    const urls = stills
      .map((p) => assetUrl(p))
      .filter((u): u is string => u !== null);

    const res: StoryboardResponse = { stills: urls };
    return Response.json(res, { status: 200 });
  } catch (err) {
    const e = err as { message?: string; detail?: string };
    return Response.json(
      { error: e?.message ?? "storyboard failed", detail: e?.detail },
      { status: 500 },
    );
  }
}

